async function upload(e){error.value=''; const file=e.target.files[0]; if(!file)return;try{if(file.size>20*1024*1024)throw Error('Choose a JSON file smaller than 20 MB.');loadFrames(JSON.parse(await file.text()));source.value=file.name}catch(err){error.value=err.message}finally{e.target.value=''}}
async function loadEngineExample(){
 loading.value=true;error.value=''
 try{
  const response=await fetch(`${import.meta.env.BASE_URL}examples/engine-timeline.json`)
  if(!response.ok)throw Error(`Could not load engine example (${response.status}).`)
  loadFrames(await response.json());source.value='Engine output · synthetic inputs';selected.value=null
 }catch(err){error.value=err.message}finally{loading.value=false}
}
function useDemo(){loadFrames(demo());source.value='Synthetic demonstration';selected.value=null;error.value=''}
async function loadCoupledExample(){
 loading.value=true;error.value=''
 try{
  const response=await fetch(`${import.meta.env.BASE_URL}coupled/engine-timeline.json`)
  if(!response.ok)throw Error(`Could not load coupled wind example (${response.status}).`)
  loadFrames(await response.json());source.value='Engine output · coupled wind';layer.value='wind';selected.value=null
 }catch(err){error.value=err.message}finally{loading.value=false}
}
watch([data,layer,vectors,terrainEnabled,exaggeration,adjustedTemperature,cloudsEnabled,systemsEnabled,cloudVolumes,frontOverlay,view,mapLayers,waterLayers,hazardLayers,oceanLayers,polarLayers,coastLayers,selected],draw,{deep:true})
onMounted(()=>{try{scene=new THREE.Scene();scene.background=new THREE.Color('#09151d');scene.fog=new THREE.Fog('#09151d',65,110);camera=new THREE.PerspectiveCamera(42,1,.1,200);renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));host.value.appendChild(renderer.domElement);scene.add(new THREE.AmbientLight(0xd6efff,2));const sun=new THREE.DirectionalLight(0xffffff,3);sun.position.set(12,30,20);scene.add(sun);const floor=new THREE.GridHelper(60,30,0x28404b,0x142b36);floor.position.y=-.05;scene.add(floor);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.maxPolarAngle=Math.PI/2.05;controls.minDistance=8;controls.maxDistance=85;reset();renderer.domElement.addEventListener('click',pick);observer=new ResizeObserver(()=>{const {width,height}=host.value.getBoundingClientRect();renderer.setSize(width,height);camera.aspect=width/height;camera.updateProjectionMatrix()});observer.observe(host.value);draw();const tick=()=>{frame=requestAnimationFrame(tick);controls.update();renderer.render(scene,camera)};tick()}catch(err){fallback.value=true;error.value='WebGL unavailable in this browser. Showing an interactive 2D field instead.'}})
onBeforeUnmount(()=>{stop();cancelAnimationFrame(frame);observer?.disconnect();controls?.dispose();disposeGroup();scene?.traverse(o=>{o.geometry?.dispose();o.material?.dispose()});renderer?.dispose()})
</script>
<template>
 <div class="shell">
  <header><a class="brand" href="#"><span class="mark">T</span><span>TERRAFLUX<small>PHYSICS OBSERVATORY</small></span></a><span class="status"><i></i> LOCAL WORKSPACE</span><label class="upload">↥ Open JSON<input type="file" accept=".json,application/json" @change="upload"></label></header>
  <main><aside><div class="eyebrow">EXPERIMENT / 001</div><h1>Weather,<br>in perspective.</h1><p class="intro">Explore the fields behind the physics. Inspect temperature, wind and accumulated rainfall on a shared grid.</p>
   <section class="layer-groups"><div class="section-label">01 / FIELD LAYERS</div><label class="toggle layer-filter" title="Hide the layers (and groups) the loaded data cannot show."><input type="checkbox" v-model="onlyAvailable"> Only layers with data ({{availableLayerCount}} of {{LAYERS.length}})</label><details v-for="g in layerGroups" :key="g.id" class="layer-group" :open="openGroups.includes(g.id)" @toggle="onGroupToggle(g.id,$event)"><summary :title="g.tooltip"><span>{{g.title}}</span><small>{{g.available}}/{{g.layers.length}}{{g.active?' · ●':''}}</small></summary><button v-for="l in g.shown" :key="l.key" class="layer" :class="{active:layer===l.key}" :disabled="!l.available" :title="l.tooltip" @click="layer=l.key"><span>{{l.title}}<small>{{l.subtitle}}</small></span><span>{{layer===l.key?'●':'○'}}</span></button></details><template v-if="data.atmosphere"><label class="toggle"><input type="checkbox" v-model="cloudsEnabled"> Cloud overlay</label><label class="toggle"><input type="checkbox" v-model="systemsEnabled"> Weather-system markers</label><p class="hint">Synthetic pressure, clouds and front. Cloud height is schematic; these fields do not drive the local physics.</p></template><p v-if="data.coupled" class="hint">Coupled engine run: wind from the static pressure field, Coriolis and friction; density diagnosed from temperature and humidity feeds back into the wind; temperature and humidity are carried by the wind with configurable diffusion.<br>Diffusion T {{data.coupled.request.diffusion.temperature_m2_s}} · q {{data.coupled.request.diffusion.humidity_m2_s}} · momentum {{data.coupled.request.diffusion.momentum_m2_s}} m²/s · friction {{data.coupled.request.atmosphere.surface_friction_coefficient_s}} 1/s · Coriolis {{data.coupled.request.atmosphere.coriolis_mode}} · density {{data.coupled.request.density_mode}}<template v-if="data.coupled.columns"><br>Vertical columns: hydrostatic layers, convective adjustment and a lifted surface parcel give cloud base, equilibrium level and CAPE per cell. Diagnostic only; no surface fluxes resupply heat or moisture.</template></p><template v-if="data.clouds"><label class="toggle"><input type="checkbox" v-model="cloudVolumes"> Cloud volumes (base → top)</label><label class="toggle"><input type="checkbox" v-model="frontOverlay"> Front overlay (blue cold · red warm · purple stationary)</label><p class="hint">{{data.clouds.synthetic?'Synthetic mock in the documented cloud-formation format; illustration only.':'Engine diagnosis: fronts from the temperature gradient, advection and convergence; convection from the heated surface parcel; combined where frontal lifting releases it.'}}<br>Heating now {{data.clouds.heating.toFixed(1)}} K · lifting over {{(data.clouds.config.lifting_time_scale_s/3600).toFixed(0)}} h · warm slope 1:{{(1/data.clouds.config.warm_front_slope).toFixed(0)}} · cold slope 1:{{(1/data.clouds.config.cold_front_slope).toFixed(0)}}</p></template><label class="toggle"><input type="checkbox" v-model="vectors"> Wind direction vectors</label><template v-if="data.terrain"><label class="toggle"><input type="checkbox" v-model="terrainEnabled"> Place fields on terrain</label><label class="toggle">Height scale {{exaggeration}}× <input aria-label="Terrain vertical exaggeration" type="range" min="1" max="5" step="0.5" v-model="exaggeration"></label><label v-if="data.terrainTemperature" class="toggle"><input type="checkbox" v-model="adjustedTemperature"> Terrain-adjusted temperature</label><p v-if="data.terrainTemperature" class="hint">Lapse rate {{data.terrainTemperature.lapse_rate_k_per_m*1000}} K/km · reference {{data.terrainTemperature.reference_elevation_m}} m<br>Diagnostic adjustment; no feedback into transport.</p><p class="hint">{{data.terrain.source_id}} · {{data.terrain.vertical_reference}}<br>Geometry is a display layer; lapse-rate adjustment is optional.</p></template></section>
   <section v-if="view==='map'" class="map-layers"><div class="section-label">01b / WEATHER MAP LAYERS</div><p class="hint">Switch layers on and off to compose the map. Engine or labelled mock output only; no rendering of external map tiles yet.</p>
    <label class="toggle">Base field <select v-model="mapLayers.base"><option value="temperature">Air temperature</option><option value="pressure">Surface pressure</option><option v-if="data.terrain" value="terrain">Terrain (hillshade)</option><option value="none">None (dark)</option></select></label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.relief" :disabled="!data.terrain"> Relief (3D terrain, height scale {{exaggeration}}×)</label>
    <label v-if="data.terrain" class="toggle">Height scale <input aria-label="Map relief exaggeration" type="range" min="1" max="5" step="0.5" v-model="exaggeration"></label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.lifting" :disabled="!data.orography"> Orographic lifting (blue up-slope · orange descent)</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.foehn" :disabled="!data.orography"> Foehn cells (F)</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.coldPools" :disabled="!data.orography"> Cold-air pools (❄)</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.oroPrecip" :disabled="!data.orography"> Orographic precipitation (●)</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.blocking" :disabled="!data.orography"> Blocked flow (Froude)</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.isobars"> Isobars every <select v-model.number="mapLayers.isobarIntervalHpa"><option :value="1">1</option><option :value="2">2</option><option :value="4">4</option></select> hPa</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.fronts" :disabled="!data.clouds"> Fronts (cold blue · warm red · stationary purple)</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.clouds" :disabled="!data.clouds"> Cloud cover by genus</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.volumes" :disabled="!data.clouds"> Cloud volumes (3D base → top)</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.precipitation" :disabled="!data.precipitation"> Precipitation rate shading</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.symbols" :disabled="!data.precipitation"> Precipitation symbols (● rain ▽ showers ✱ snow ▲ sleet ’ drizzle)</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.hazards" :disabled="!data.precipitation"> Thunderstorm ⚡ and hail ◆ markers</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.wind"> Wind vectors</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.landSea" :disabled="!data.surface"> Land / sea</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.storms" :disabled="!data.storms"> Tropical cyclones (centres, category, tracks, ✖ landfall ⊕ merger ✦ genesis)</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.stormWind" :disabled="!data.storms"> Storm wind field (category colours)</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.surge" :disabled="!data.storms"> Storm surge on the coast</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.tornado" :disabled="!data.severe"> Tornado risk (STP class) and 🌪 where possible</label>
    <p v-if="!data.clouds" class="hint">Load the cloud formation example or mock for fronts, clouds and precipitation layers.</p>
   </section>
   <section v-if="view==='water'" class="map-layers"><div class="section-label">01c / CATCHMENT LAYERS</div><p class="hint">Where the water goes: rivers sized by upstream area and coloured by discharge, lakes at their level, snow, overland water and rain over the relief. Click a cell to trace its water to the outlet.</p>
    <label class="toggle">Base <select v-model="waterLayers.base"><option value="terrain">Terrain (hillshade)</option><option value="basins">Drainage basins</option><option value="groundwater">Water-table depth (dark = deep)</option><option value="saturation">Soil saturation</option></select></label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.relief"> Relief (3D terrain, height scale {{exaggeration}}×)</label>
    <label class="toggle">Height scale <input aria-label="Catchment relief exaggeration" type="range" min="1" max="5" step="0.5" v-model="exaggeration"></label>
    <label class="toggle"><input type="checkbox" v-model="waterLayers.rivers"> River network (width ∝ upstream area · brightness ∝ discharge)</label>
    <label class="toggle"><input type="checkbox" v-model="waterLayers.lakes"> Lakes (depth above the lake floor)</label>
    <label class="toggle"><input type="checkbox" v-model="waterLayers.labels"> Lake labels with level</label>
    <label class="toggle"><input type="checkbox" v-model="waterLayers.surface"> Overland / floodplain water</label>
    <label class="toggle"><input type="checkbox" v-model="waterLayers.snow"> Snowpack</label>
    <label class="toggle"><input type="checkbox" v-model="waterLayers.rain"> Rainfall rate tint</label>
    <label class="toggle"><input type="checkbox" v-model="waterLayers.arrows"> Flow direction arrows (D8)</label>
   </section>
   <section v-if="view==='hazards'" class="map-layers"><div class="section-label">01d / HAZARD LAYERS</div><p class="hint">What massive rain does: flood depth × velocity classes, channels above bankfull in orange, erosion (red) and deposition (tan), landslides ▲ with debris runout, rainfall intensity–duration warnings (!) and slopes still unstable.</p>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.relief"> Relief (3D terrain)</label>
    <label class="toggle"><input type="checkbox" v-model="hazardLayers.flood"> Flooding (<span v-for="c in FLOOD_CLASSES.slice(1)" :key="c.key" :style="{color:c.color}">■ {{c.key}} </span>)</label>
    <label class="toggle"><input type="checkbox" v-model="hazardLayers.sediment"> Erosion / deposition</label>
    <label class="toggle"><input type="checkbox" v-model="hazardLayers.landslides"> Landslides ▲ (up to the current time)</label>
    <label class="toggle"><input type="checkbox" v-model="hazardLayers.runout"> Debris runout paths</label>
    <label class="toggle"><input type="checkbox" v-model="hazardLayers.unstable"> Unstable slopes (failed, not yet drained)</label>
    <label class="toggle"><input type="checkbox" v-model="hazardLayers.threshold"> Rainfall intensity–duration threshold exceeded (!)</label>
    <label class="toggle"><input type="checkbox" v-model="hazardLayers.stability"> Factor of safety shading (red < 1 · orange < 1.3 · yellow < 2 · green)</label>
   </section>
   <section v-if="view==='ocean'" class="map-layers"><div class="section-label">01e / OCEAN STREAM LAYERS</div><p class="hint">The streams (core streamlines sized by transport, coloured by speed), the current field, the saltiness of the water, the river exchange points ⊕ with their plumes, the mixing fronts and the deep-water formation sites ⇩ where the overturning sinks. Click a cell for the local state and its stream.</p>
    <label class="toggle">Water colour <select v-model="oceanLayers.base"><option value="surface">Surface salinity (fresh ↔ salty)</option><option value="salinity">Layer salinity</option><option value="speed">Current speed</option><option value="temperature">Layer temperature</option><option value="thickness">Thermocline depth</option><option value="freshwater">Freshwater fraction</option><option v-if="data.ocean?.processes?.length" value="sst">Sea-surface temperature (run range)</option><option v-if="data.ocean?.thermal" value="mld">Mixed-layer depth (pale shallow → deep blue)</option><option v-if="data.ocean?.airSea" value="netheat">Net air–sea heat flux (blue loss ↔ red gain)</option><option v-if="data.ocean?.airSea" value="evaporation">Evaporation (dark → yellow 15 mm/day)</option><option v-if="data.ocean?.oxygen" value="oxygen">Surface oxygen capacity (purple low ↔ green high)</option><option value="none">None (deep blue)</option></select></label>
    <label class="toggle"><input type="checkbox" v-model="oceanLayers.streams"> Streams (core streamlines)</label>
    <label class="toggle"><input type="checkbox" v-model="oceanLayers.arrows"> Current arrows (length ∝ speed)</label>
    <label class="toggle"><input type="checkbox" v-model="oceanLayers.rivers"> River mouths ⊕ (exchange points)</label>
    <label class="toggle"><input type="checkbox" v-model="oceanLayers.plumes"> Freshwater plumes (pale tint)</label>
    <label class="toggle"><input type="checkbox" v-model="oceanLayers.fronts"> Mixing fronts (white)</label>
    <label class="toggle"><input type="checkbox" v-model="oceanLayers.formation"> Deep-water formation ⇩ (purple)</label>
    <label class="toggle"><input type="checkbox" v-model="oceanLayers.sponge"> Open-boundary sponge rows</label>
    <label class="toggle"><input type="checkbox" v-model="oceanLayers.labels"> Labels (stream names, river discharge and salinity)</label>
    <template v-if="data.ocean?.processes?.length"><p class="hint">Rain, evaporation and heat: rain tints sea and land by rate; the coastal band (tan) drains straight to the sea (blue arrows, length ∝ water still stored on land), land beyond it is left to the rivers. Lenses are fresh surface water by source. The yellow ring marks the water column shown below the map.</p>
    <label class="toggle"><input type="checkbox" v-model="oceanLayers.rain" :disabled="!data.ocean.rain"> Rain on sea and land (rate tint)</label>
    <label class="toggle"><input type="checkbox" v-model="oceanLayers.coast" :disabled="!data.ocean.rain"> Coastal band draining directly to the sea (tan)</label>
    <label class="toggle"><input type="checkbox" v-model="oceanLayers.runoff" :disabled="!data.ocean.rain"> Coastal runoff → sea (arrows, stored water on land)</label>
    <label class="toggle"><input type="checkbox" v-model="oceanLayers.lenses"> Surface lens labels (rain · coastal runoff · river · glacial)</label></template>
    <template v-if="data.ocean?.polar"><p class="hint">Polar processes: sea ice drawn white over the water (opacity = concentration, brightness = thickness), the coupled ice sheet white on land (reddish where it melts faster than it snows), the yellow ring where extra meltwater is hosed into the sea.</p>
    <label class="toggle"><input type="checkbox" v-model="oceanLayers.seaIce" :disabled="!data.ocean.seaIce"> Sea ice (white, concentration)</label>
    <label class="toggle"><input type="checkbox" v-model="oceanLayers.iceDrift" :disabled="!data.ocean.seaIce"> Sea-ice drift (white arrows: current + 2 % of the wind)</label>
    <label class="toggle"><input type="checkbox" v-model="oceanLayers.iceSheet" :disabled="!data.ocean.iceSheet"> Ice sheet on land (thickness · melting margin)</label>
    <label class="toggle"><input type="checkbox" v-model="oceanLayers.hosing" :disabled="!data.ocean.forcing?.hosing"> Meltwater hosing region (yellow ring)</label></template>
   </section>
   <section v-if="view==='polar'&&data.polar" class="map-layers"><div class="section-label">01f / POLAR MELT LAYERS</div><p class="hint">Greenland of the “{{data.polar.block.map_scenario}}” scenario in {{data.polar.year}}: relief of bed + ice (height scale {{exaggeration}}×). The charts and the table below compare all scenarios; choose which one the metrics, the freshwater chart and the equilibrium diagram follow.</p>
    <label class="toggle">Ice colour <select v-model="polarLayers.base"><option value="thickness">Ice thickness (pale thin → white thick)</option><option value="smb">Surface mass balance (red melt ↔ blue snow)</option><option value="melt">Surface melt</option><option value="temperature">Surface air temperature (annual)</option></select></label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.relief"> Relief (bed + ice)</label>
    <label class="toggle">Height scale <input aria-label="Polar relief exaggeration" type="range" min="1" max="5" step="0.5" v-model="exaggeration"></label>
    <label class="toggle">Scenario in focus <select v-model="polarLayers.scenario"><option value="">{{data.polar.block.map_scenario}} (map)</option><option v-for="s in data.polar.block.scenarios" :key="s.name" :value="s.name">{{s.name}}</option></select></label>
   </section>
   <section v-if="view==='coast'&&data.coast" class="map-layers"><div class="section-label">01g / SEA LEVEL &amp; COAST LAYERS</div><p class="hint">The coast in {{data.coast.year}} under “{{coastScenario}}”: <span style="color:#ff8a8a">red</span> land lost to the sea (permanently under high water or eroded), <span style="color:#8fd3ff">blue</span> flooded by today's 100-year storm on the risen sea, <span style="color:#ffb867">orange</span> below high water but kept dry by defences, black defences, blue rivers (white: salt water). {{coastIsMap?'Depths from the engine maps.':'Other scenarios show when each cell is first lost or flooded (the depth maps are for '+data.coast.block.map_scenario+').'}}</p>
    <label class="toggle" title="The colour of the land (the sea is coloured by depth).">Land colour <select v-model="coastLayers.base"><option value="terrain">Elevation (hillshaded)</option><option value="year">Year the land is lost (red soon → yellow late)</option><option value="frequency">Today's 100-year flood: how often now (red yearly → green rare)</option><option value="population">Population density</option><option value="subsidence">Land subsidence</option><option value="setup">Sea: wind setup of the design storm</option></select></label>
    <label class="toggle" title="Which scenario the metrics, tables, charts and first-year maps follow.">Scenario in focus <select v-model="coastLayers.scenario"><option value="">{{data.coast.block.map_scenario}} (maps)</option><option v-for="x in data.coast.block.scenarios" :key="x.name" :value="x.name">{{x.name}}</option></select></label>
    <label class="toggle" title="Land under the daily high water of the risen sea (reached by the sea) or eroded from sandy shores by the Bruun rule."><input type="checkbox" v-model="coastLayers.lost"> Land lost to the sea (red)</label>
    <label class="toggle" title="The 100-year storm: surge on top of high tide and the risen sea plus the wind setup, losing 0.2 m per km inland and far less along rivers."><input type="checkbox" v-model="coastLayers.storm"> Flooded by the 100-year storm (blue by depth)</label>
    <label class="toggle" title="Land lying below the daily high water that only the dikes keep dry: it depends on the defences."><input type="checkbox" v-model="coastLayers.protected"> Below high water behind defences (orange)</label>
    <label class="toggle" title="Dikes and flood walls, drawn at their crest height; they hold until the water overtops them."><input type="checkbox" v-model="coastLayers.defences"> Defences (black, raised)</label>
    <label class="toggle" title="River channels; white where the water is salty (salt intrusion from the sea)."><input type="checkbox" v-model="coastLayers.rivers"> Rivers and salt intrusion</label>
    <label class="toggle" title="The onshore wind of the design storm that piles water up over the shallow shelf."><input type="checkbox" v-model="coastLayers.wind"> Design-storm wind</label>
    <label class="toggle"><input type="checkbox" v-model="coastLayers.labels"> Labels (regions, rivers)</label>
    <label class="toggle">Height scale <input aria-label="Coast relief exaggeration" type="range" min="1" max="5" step="0.5" v-model="exaggeration"></label>
   </section>
   <section><div class="section-label">02 / DATA SOURCE</div><strong class="source">{{source}}</strong><p class="hint">{{source==='Synthetic demonstration'?'Illustrative fields only. These values are not engine output or live observations.':source==='Regional weather · synthetic'?'Analytic 1,200 × 900 km weather illustration. Low/high pressure, a moving front and cloud bands; not solver output.':source==='Engine output · synthetic inputs'?'C++ dry transport + radar rain estimation + accumulation + gridding. Synthetic inputs; not live weather.':source==='Engine output · coupled wind'?'C++ coupled wind / moist-layer model on synthetic Gaussian pressure systems. Pressure is prescribed; not live weather or a forecast.':source==='Engine output · cloud formation'?'C++ coupled model with column and cloud-formation diagnostics: cold/warm fronts, frontal and convective cloud, afternoon thunderstorms. Synthetic inputs; rule-of-thumb cloud types.':source==='Cloud formation · synthetic mock'?'Hand-built mock in the documented cloud-formation format (moving warm and cold fronts, diurnal convection, a synthetic hurricane and tornado risk). Not solver output.':source==='Engine output · Alps foehn'?'C++ coupled model over a synthetic east-west Alpine ridge with a foreland basin: southerly flow, orographic precipitation on the south side, foehn warming and drying to the north, nocturnal cold pools in the basin. Synthetic terrain; parametrised orography, not a forecast.':source==='Engine output · polar melt & overturning'?'C++ Greenland ice sheet (shallow-ice flow, degree-day melt with the melt-elevation feedback, ocean-driven frontal melt), a central-Arctic sea-ice column and a two-box Atlantic overturning calibrated to 17 Sv, under three warming scenarios 1850–2300 with a 9-member uncertainty ensemble. Synthetic geometry, conceptual overturning: read dates as scenario-relative, not as a forecast.':source==='Engine output · sea level & coasts'?'C++ sea-level budget (thermal expansion, glaciers, Antarctica, land water, and Greenland from the polar-melt run) turned into coastal impacts on a synthetic 420 × 252 km coast: a subsiding delta with polders and dikes, an estuary city, barrier islands with a lagoon, cliffs and low islands. Land lost at high water (bathtub with connectivity), 100-year storm floods with wind setup, Bruun erosion, rivers pushed back and salt intrusion, year by year to 2300. Synthetic coast; a demonstration, not a local projection.':source==='Engine output · polar ocean'?'C++ layered ocean with sea ice and a coupled Greenland-like ice sheet in a synthetic 3,400 × 4,200 km North-Atlantic-like basin with seasons: air warming ramps up by 0.4 K/yr to +4 K (2.5× in the north) while extra meltwater is hosed near the sinking region (up to 0.5 Sv). Watch the winter sea ice shrink, the ice sheet melt and the deep-water formation weaken. Ten model years after a spin-up; a process demonstration, not a projection.':source==='Engine output · ocean heat & rain'?'C++ ocean with rain, evaporation, air–sea heat exchange and a 10-layer temperature/salinity column in a synthetic late-summer subtropical basin: a tropical rain band crosses the sea and makes landfall, a storm floods the coastal plain, a cold dry outbreak draws heat and water out of the sea, the sun drives a daily warm layer. Synthetic forcing; not an ocean forecast.':source==='Engine output · Atlantic streams'?'C++ reduced-gravity ocean layer on a beta-plane in a synthetic Atlantic-like basin: a double-gyre wind drives a Gulf-Stream-like western boundary current that separates at a cape, a cold north-western patch forms deep water (the overturning), rivers and a meltwater pulse pour fresh water in. Idealised and closed; not an ocean forecast.':source==='Engine output · alpine flood'?'C++ catchment hydrology on a synthetic pre-alpine range draining to a southern sea: two days of stratiform rain, an eight-hour cloudburst on the range, then a shower. Rivers, lakes, groundwater, floods, erosion and landslides from the kernel; synthetic terrain and forcing, not a forecast.':source==='Engine output · hurricane landfall'?'C++ coupled model with tropical-cyclone objects: two seeds merge, the storm intensifies toward its potential intensity over a 29 °C sea, makes landfall on the western coast and decays inland. Synthetic inputs; parametrised storm physics, not a forecast.':'Loaded in this browser only. No upload service or database.'}}</p><label v-if="data.surfaceWater" class="compare-upload" title="Load a second timeline on the same grid and forcing to compare against the current one.">Open comparison JSON<input type="file" accept=".json,application/json" @change="uploadComparison"></label><details v-for="g in EXAMPLE_GROUPS" :key="g.id" class="example-group" :open="openExamples.includes(g.id)" @toggle="onExampleToggle(g.id,$event)"><summary :title="`${g.examples.length} examples`"><span>{{g.title}}</span><small>{{g.examples.length}}</small></summary><button v-for="e in g.examples" :key="e.action" class="example-button" :disabled="loading&&e.action.startsWith('load')" :title="e.tooltip" @click="runExample(e.action)">{{e.action==='loadEngineExample'&&loading?'Loading…':e.label}}</button></details><button class="text-button" @click="useDemo">↻ Load synthetic demo</button></section>
   <section class="inspection"><div class="section-label">03 / CELL INSPECTOR</div><template v-if="chosen"><h2>{{values[chosen.i]===null?(layer==='aspect'?'Undefined (flat)':'No data'):values[chosen.i]?.toFixed(2)}} <small>{{unit}}</small></h2><p>Column {{chosen.x}} · Row {{chosen.y}} · Index {{chosen.i}}</p><p>East {{(grid.origin_east_m+(chosen.x+.5)*grid.spacing_east_m).toFixed(0)}} m · North {{(grid.origin_north_m+(chosen.y+.5)*grid.spacing_north_m).toFixed(0)}} m</p><p v-if="data.atmosphere">Cloud {{(data.atmosphere.cloud[chosen.i]*100).toFixed(1)}}% · Pressure {{data.atmosphere.pressure[chosen.i].toFixed(1)}} hPa<br>Relative humidity {{data.atmosphere.humidity[chosen.i].toFixed(1)}}%</p><p v-if="data.coupled">Pressure {{(data.coupled.pressure[chosen.i]/100).toFixed(1)}} hPa · Density {{data.coupled.density[chosen.i].toFixed(4)}} kg/m³<br>Specific humidity {{(data.coupled.specificHumidity[chosen.i]*1000).toFixed(2)}} g/kg · Relative humidity {{data.coupled.humidity[chosen.i].toFixed(1)}}%<br>Coriolis f {{data.coupled.coriolis[chosen.i].toExponential(3)}} 1/s</p><p v-if="data.clouds">Cloud: <strong>{{cloudTypeInfo(data.clouds.type[chosen.i]).label}}</strong><template v-if="data.clouds.type[chosen.i]!=='none'"> · base {{data.clouds.base[chosen.i].toFixed(0)}} m · top {{data.clouds.top[chosen.i].toFixed(0)}} m · cover {{(data.clouds.fraction[chosen.i]*100).toFixed(0)}}%<br>Mechanism {{data.clouds.mechanism[chosen.i]}} · trigger {{data.clouds.trigger[chosen.i]}}{{data.clouds.thunderstorm[chosen.i]?' · thunderstorm':''}}</template><br>Front {{data.clouds.frontType[chosen.i]}} · |∇T| {{(data.clouds.gradient[chosen.i]*1e5).toFixed(2)}} K/100 km · advection {{(data.clouds.advection[chosen.i]*3600).toFixed(2)}} K/h · divergence {{data.clouds.divergence[chosen.i].toExponential(2)}} 1/s<br>{{data.clouds.distance[chosen.i]===null?'No front in the domain':`Nearest front ${(data.clouds.distance[chosen.i]/1000).toFixed(0)} km · ${data.clouds.side[chosen.i]===1?'warm side':data.clouds.side[chosen.i]===-1?'cold side':'on the front'}`}} · lifting {{data.clouds.lifting[chosen.i].toFixed(0)}} m · heated CAPE {{data.clouds.cape[chosen.i].toFixed(0)}} / CIN {{data.clouds.cin[chosen.i].toFixed(0)}} J/kg</p><p v-if="data.precipitation">Precipitation: <strong>{{precipitationTypeInfo(data.precipitation.type[chosen.i]).label}}</strong><template v-if="data.precipitation.type[chosen.i]!=='none'"> · {{data.precipitation.intensity[chosen.i]}} {{data.precipitation.character[chosen.i]}} · {{data.precipitation.rate[chosen.i].toFixed(2)}} mm/h for {{(data.precipitation.duration[chosen.i]*100).toFixed(0)}}% of the interval → {{data.precipitation.accumulation[chosen.i].toFixed(1)}} mm · phase {{data.precipitation.phase[chosen.i]}}</template><template v-if="data.precipitation.virga[chosen.i]"> · virga (evaporates aloft)</template><br>{{data.precipitation.hazards[chosen.i].length?data.precipitation.hazards[chosen.i].map(h=>HAZARD_LABELS[h]).join(' · '):'no hazards'}}<template v-if="data.precipitation.hail[chosen.i]>0"> · hail up to {{data.precipitation.hail[chosen.i].toFixed(1)}} cm</template><br>Wet-bulb {{(data.precipitation.wetBulb[chosen.i]-273.15).toFixed(1)}} °C · freezing level {{data.precipitation.freezingLevel[chosen.i]===null?'none':data.precipitation.freezingLevel[chosen.i].toFixed(0)+' m'}} · precipitable water {{data.precipitation.precipitableWater[chosen.i].toFixed(1)}} mm<template v-if="data.precipitation.baseTemperature[chosen.i]!==null"> · cloud {{(data.precipitation.baseTemperature[chosen.i]-273.15).toFixed(0)}} °C at base, {{(data.precipitation.topTemperature[chosen.i]-273.15).toFixed(0)}} °C at top · lifting {{data.precipitation.updraft[chosen.i].toFixed(2)}} m/s</template></p><p v-if="data.orography">Orography: elevation {{data.terrain.values[chosen.i].toFixed(0)}} m · surface pressure {{(data.orography.surfacePressure[chosen.i]/100).toFixed(1)}} hPa · lifting {{data.orography.lifting[chosen.i].toFixed(3)}} m/s ({{data.orography.lifting[chosen.i]>0.01?'up-slope':data.orography.lifting[chosen.i]<-0.01?'descending':'level'}}) · contour {{data.orography.orientation[chosen.i]===null?'flat':data.orography.orientation[chosen.i].toFixed(0)+'° from north'}}<br>Cross-barrier {{data.orography.cross[chosen.i].toFixed(1)}} m/s · along-barrier {{data.orography.along[chosen.i].toFixed(1)}} m/s · obstacle ahead {{data.orography.obstacle[chosen.i].toFixed(0)}} m · Froude {{data.orography.froude[chosen.i]===null?'—':data.orography.froude[chosen.i].toFixed(2)}} · blocked {{(data.orography.blocked[chosen.i]*100).toFixed(0)}}%<br>Valley depth {{data.orography.valley[chosen.i].toFixed(0)}} m · cold pool {{data.orography.coldPool[chosen.i].toFixed(1)}} K{{data.orography.coldPoolFlag[chosen.i]?' ❄':''}} · foehn {{data.orography.foehn[chosen.i]?`+${data.orography.foehnWarming[chosen.i].toFixed(1)} K`:'no'}} · orographic precipitation {{data.orography.precipRate[chosen.i].toFixed(2)}} mm/h ({{data.orography.cumulative[chosen.i].toFixed(1)}} mm so far)</p><p v-if="data.hydrology">Catchment: <strong>{{data.hydrology.network.ocean[chosen.i]?'sea':data.hydrology.network.lake_id[chosen.i]>=0?`lake ${data.hydrology.network.lake_id[chosen.i]+1}`:data.hydrology.network.channel[chosen.i]?`river reach (Strahler ${data.hydrology.network.strahler_order[chosen.i]})`:'hillslope'}}</strong><template v-if="!data.hydrology.network.ocean[chosen.i]"> · upstream {{data.hydrology.network.upstream_area_km2[chosen.i].toFixed(0)}} km² · {{pathSummary}}<br>Rain {{data.hydrology.rain[chosen.i].toFixed(1)}} mm/h · snow {{data.hydrology.snow[chosen.i].toFixed(0)}} mm · surface water {{data.hydrology.surface[chosen.i].toFixed(1)}} mm · soil {{(data.hydrology.saturation[chosen.i]*100).toFixed(0)}} % saturated · water table {{data.hydrology.waterTable[chosen.i].toFixed(1)}} m down<template v-if="data.hydrology.network.channel[chosen.i]"><br>Discharge {{data.hydrology.discharge[chosen.i].toFixed(2)}} m³/s · depth {{data.hydrology.channelDepth[chosen.i].toFixed(2)}} / bankfull {{data.hydrology.network.bankfull_depth_m[chosen.i].toFixed(2)}} m · width {{data.hydrology.network.channel_width_m[chosen.i].toFixed(0)}} m · sediment {{data.hydrology.sediment[chosen.i].toFixed(2)}} kg/s</template><template v-if="data.hydrology.network.lake_id[chosen.i]>=0"><br>Lake level {{data.hydrology.lakeLevel[data.hydrology.network.lake_id[chosen.i]].toFixed(1)}} m · depth here {{data.hydrology.lakeDepth[chosen.i].toFixed(1)}} m · volume {{(data.hydrology.lakeVolume[data.hydrology.network.lake_id[chosen.i]]/1e6).toFixed(2)}} / {{(data.hydrology.network.lakes[data.hydrology.network.lake_id[chosen.i]].capacity_m3/1e6).toFixed(2)}} hm³</template><br>Hazards: flood <strong :style="{color:floodClassInfo(data.hydrology.floodClass[chosen.i]).color||'inherit'}">{{floodClassInfo(data.hydrology.floodClass[chosen.i]).key}}</strong> · erosion {{data.hydrology.erosion[chosen.i].toFixed(2)}} mm · deposition {{data.hydrology.deposition[chosen.i].toFixed(2)}} mm · factor of safety {{data.hydrology.fs[chosen.i]===null?'n/a (flat or water)':data.hydrology.fs[chosen.i].toFixed(2)}}{{data.hydrology.landslide[chosen.i]?' · ▲ landslide this step':data.hydrology.unstable[chosen.i]?' · unstable':''}}{{data.hydrology.threshold[chosen.i]?' · ! rainfall threshold exceeded':''}} · regolith {{data.hydrology.network.regolith_depth_m[chosen.i].toFixed(2)}} m · slope {{(Math.atan(data.hydrology.network.slope[chosen.i])*180/Math.PI).toFixed(1)}}°</template></p><p v-if="data.coast"><template v-if="data.coast.sea[chosen.i]">Sea · {{(-data.terrain.values[chosen.i]).toFixed(1)}} m deep · today's design-storm wind setup {{data.coast.block.today.setup_m[chosen.i].toFixed(2)}} m</template><template v-else><strong>{{data.coast.block.region[chosen.i]>=0?data.coast.block.region_names[data.coast.block.region[chosen.i]]:'Other land'}}</strong> · {{COAST_TYPES[data.coast.block.coast_type[chosen.i]]}} · {{data.terrain.values[chosen.i].toFixed(2)}} m above today's mean sea level{{coastStatic.defence.has(chosen.i)?` · defence crest ${coastStatic.defence.get(chosen.i).toFixed(1)} m`:''}}{{coastStatic.river.has(chosen.i)?` · river ${data.coast.block.rivers[coastStatic.river.get(chosen.i)].name}`:''}}<br>{{fmtPeople(data.coast.block.population[chosen.i])}} people · sinking {{data.coast.block.subsidence_mm_yr[chosen.i].toFixed(1)}} mm/yr · relative rise by {{data.coast.year}} {{cellFrequency(data.coast,coastScenario,chosen.i).relative_rise_m.toFixed(2)}} m<template v-if="coastCoastal[chosen.i]"> · today's 100-year flood now {{fmtYears(cellFrequency(data.coast,coastScenario,chosen.i).return_years)}}</template><br>Under “{{coastScenario}}”: {{coastYears.lost[chosen.i]!==null?`lost in ${coastYears.lost[chosen.i]}`:'not lost by '+data.coast.block.output_years.at(-1)}} · {{coastYears.storm[chosen.i]===data.coast.block.reference_year?'flooded by the 100-year storm already today':coastYears.storm[chosen.i]!==null?`first flooded by the 100-year storm in ${coastYears.storm[chosen.i]}`:'not reached by the 100-year storm'}}<template v-if="coastIsMap"><br>{{data.coast.year}}: {{data.coast.lost[chosen.i]>=1?`under high water (${data.coast.inundation[chosen.i].toFixed(2)} m deep)`:data.coast.lost[chosen.i]>0?`${(data.coast.lost[chosen.i]*100).toFixed(1)} % eroded (shore retreat ${data.coast.erosion[chosen.i].toFixed(0)} m)`:data.coast.protectedLow.has(chosen.i)?'below high water, kept dry by defences':'dry at high water'}}{{data.coast.storm[chosen.i]>0?` · ${data.coast.storm[chosen.i].toFixed(2)} m deep in the 100-year storm`:''}}{{data.coast.salt.has(chosen.i)?' · salt water in the river':''}}</template></template></p><p v-if="data.ocean">Ocean: <strong>{{data.ocean.mask[chosen.i]?(selectedStream?streamLabel(selectedStream,grid):'open water'):'land'}}</strong><template v-if="data.ocean.mask[chosen.i]"><br>Current {{data.ocean.speed[chosen.i].toFixed(2)}} m/s (u {{data.ocean.u[chosen.i].toFixed(2)}}, v {{data.ocean.v[chosen.i].toFixed(2)}}) · thermocline {{data.ocean.thickness[chosen.i].toFixed(0)}} m · {{data.ocean.thermal?'layer-mean temperature':'temperature'}} {{(data.ocean.temperature[chosen.i]-273.15).toFixed(1)}} °C<br>Salinity {{data.ocean.surfaceSalinity[chosen.i].toFixed(2)}} psu at the surface · {{data.ocean.salinity[chosen.i].toFixed(2)}} psu in the layer · fresh water {{(data.ocean.freshwater[chosen.i]*100).toFixed(1)}} %{{data.ocean.front[chosen.i]?' · mixing front':''}}{{data.ocean.sinking[chosen.i]>0?` · deep-water formation ${(data.ocean.sinking[chosen.i]*86400).toFixed(2)} m/day`:''}}{{data.ocean.spongeStrength[chosen.i]>0?' · sponge row':''}}<template v-if="selectedStream"><br>Stream: {{selectedStream.direction}} · {{selectedStream.cell_count}} cells · max {{selectedStream.max_speed_m_s.toFixed(2)}} m/s · {{selectedStream.transport_sv.toFixed(1)}} Sv · {{selectedStream.mean_salinity_psu.toFixed(2)}} psu · {{(selectedStream.mean_temperature_k-273.15).toFixed(1)}} °C</template><template v-for="p in data.ocean.exchangePoints.filter(p=>p.mouth_cell===chosen.i)" :key="p.name"><br>Exchange point {{p.name}}: {{p.discharge_m3_s.toFixed(0)}} m³/s of fresh water · plume {{p.plume_area_km2.toFixed(0)}} km² down to {{p.minimum_salinity_psu.toFixed(1)}} psu · extent {{p.plume_extent_km.toFixed(0)}} km · bearing {{p.deflection_deg.toFixed(0)}}°</template></template></p><p v-if="data.ocean?.processes?.length"><template v-if="data.ocean.mask[chosen.i]">Surface <strong>{{((data.ocean.thermal?data.ocean.thermal.sst[chosen.i]:data.ocean.temperature[chosen.i])-273.15).toFixed(2)}} °C</strong><template v-if="data.ocean.thermal"> · mixed layer {{data.ocean.thermal.mld[chosen.i].toFixed(1)}} m · isothermal layer {{data.ocean.thermal.ild[chosen.i].toFixed(1)}} m{{data.ocean.thermal.ild[chosen.i]>data.ocean.thermal.mld[chosen.i]+1?` · barrier layer ${(data.ocean.thermal.ild[chosen.i]-data.ocean.thermal.mld[chosen.i]).toFixed(1)} m`:''}}</template><template v-if="data.ocean.airSea"><br>Heat into the ocean {{data.ocean.airSea.net[chosen.i].toFixed(0)}} W/m² = sun {{data.ocean.airSea.shortwave[chosen.i].toFixed(0)}} + longwave {{data.ocean.airSea.longwave[chosen.i].toFixed(0)}} + sensible {{data.ocean.airSea.sensible[chosen.i].toFixed(0)}} + latent {{data.ocean.airSea.latent[chosen.i].toFixed(0)}}{{data.ocean.seaIce&&Math.abs(data.ocean.seaIce.toIce[chosen.i])>=1?` − to the sea ice ${data.ocean.seaIce.toIce[chosen.i].toFixed(0)} (open water ${(100-data.ocean.seaIce.concentration[chosen.i]*100).toFixed(0)} %)`:''}}{{Math.abs(data.ocean.airSea.rainHeat[chosen.i])>=1?` · rain ${data.ocean.airSea.rainHeat[chosen.i].toFixed(0)} (rain colder than the sea)`:''}}<br>Evaporation {{data.ocean.airSea.evaporation[chosen.i].toFixed(2)}} mm/day · air humidity {{(data.ocean.airSea.humidity[chosen.i]*100).toFixed(0)}} % · cloud {{(data.ocean.airSea.cloud[chosen.i]*100).toFixed(0)}} %</template><template v-if="data.ocean.rain"><br>Rain {{data.ocean.rain.rate[chosen.i].toFixed(2)}} mm/h{{data.ocean.rain.inflow[chosen.i]>0?` · coastal runoff arriving ${fmtFlow(data.ocean.rain.inflow[chosen.i])}`:''}}</template><template v-for="l in data.ocean.lenses.filter(l=>l.freshest_cell===chosen.i)" :key="'lens'+l.freshest_cell"><br>Freshest point of a {{lensLabel(l)}} (rain {{(l.source_shares.rain*100).toFixed(0)}} % · runoff {{(l.source_shares.coastal_runoff*100).toFixed(0)}} % · river {{(l.source_shares.river*100).toFixed(0)}} %{{l.source_shares.glacial!==undefined?` · glacial ${(l.source_shares.glacial*100).toFixed(0)} %`:''}})</template><template v-if="data.ocean.seaIce"><br>Sea ice {{(data.ocean.seaIce.concentration[chosen.i]*100).toFixed(0)}} %{{data.ocean.seaIce.concentration[chosen.i]>0?` · ${data.ocean.seaIce.thickness[chosen.i].toFixed(2)} m thick · ice surface ${(data.ocean.seaIce.surfaceTemperature[chosen.i]-273.15).toFixed(1)} °C · drifting ${(Math.hypot(data.ocean.seaIce.driftEast[chosen.i],data.ocean.seaIce.driftNorth[chosen.i])*86.4).toFixed(1)} km/day · the water gives it ${data.ocean.seaIce.toIce[chosen.i].toFixed(0)} W/m²`:' · open water'}}</template><template v-if="data.ocean.oxygen"><br>Dissolved-oxygen capacity at the surface {{data.ocean.oxygen[chosen.i].toFixed(0)}} µmol/kg (saturation at this temperature and salinity)</template></template><template v-else-if="data.ocean.iceSheet&&data.ocean.iceSheet.domain[chosen.i]">Ice sheet · {{data.ocean.iceSheet.thickness[chosen.i].toFixed(0)}} m of ice · surface {{data.ocean.iceSheet.surface[chosen.i].toFixed(0)}} m · bed {{data.ocean.iceSheet.bed[chosen.i].toFixed(0)}} m<br>Surface mass balance {{data.ocean.iceSheet.smb[chosen.i].toFixed(2)}} m ice/yr · melt {{data.ocean.iceSheet.melt[chosen.i].toFixed(2)}} m ice/yr</template><template v-else-if="data.ocean.rain">Land · rain {{data.ocean.rain.rate[chosen.i].toFixed(2)}} mm/h · {{data.ocean.rain.receiver[chosen.i]>=0?`coastal band: drains straight to sea cell ${data.ocean.rain.receiver[chosen.i]} · ${data.ocean.rain.store[chosen.i].toFixed(1)} mm still on the land`:'inland: its rain is left to the rivers and the catchment model'}}</template></p><p v-if="data.polar">{{data.polar.land[chosen.i]?'Greenland':'Sea'}}<template v-if="data.polar.land[chosen.i]"> · ice {{data.polar.thickness[chosen.i].toFixed(0)}} m · surface {{data.polar.surface[chosen.i].toFixed(0)}} m · bed {{data.terrain.values[chosen.i].toFixed(0)}} m<br>Surface mass balance {{data.polar.smb[chosen.i].toFixed(2)}} m ice/yr · melt {{data.polar.melt[chosen.i].toFixed(2)}} m ice/yr · annual air {{(forecast.fields.air_temperature.values[chosen.i]-273.15).toFixed(1)}} °C</template> · {{data.polar.block.map_scenario}}, {{data.polar.year}}</p><p v-if="data.storms">Storm environment: {{data.surface?.land[chosen.i]?'land':'ocean'}}{{data.surface&&!data.surface.land[chosen.i]?` · SST ${(data.surface.sst[chosen.i]-273.15).toFixed(1)} °C`:''}} · potential intensity {{data.storms.env.potential_intensity_m_s[chosen.i].toFixed(0)}} m/s · genesis index {{data.storms.env.genesis_potential_index[chosen.i].toFixed(1)}} · shear {{data.storms.env.vertical_shear_m_s[chosen.i].toFixed(1)}} m/s · vorticity {{data.storms.env.relative_vorticity_s[chosen.i].toExponential(2)}} 1/s<br>Storm wind here {{data.storms.env.storm_wind_speed_m_s[chosen.i].toFixed(1)}} m/s · pressure anomaly {{(data.storms.env.storm_pressure_anomaly_pa[chosen.i]/100).toFixed(1)}} hPa · storm rain {{data.storms.env.storm_rain_rate_mm_h[chosen.i].toFixed(1)}} mm/h<template v-if="data.storms.env.storm_surge_m[chosen.i]>0"> · surge {{data.storms.env.storm_surge_m[chosen.i].toFixed(2)}} m</template></p><p v-if="data.severe">Severe: STP {{data.severe.stp[chosen.i].toFixed(2)}} ({{data.severe.risk[chosen.i]}}){{data.severe.possible[chosen.i]?' · 🌪 tornado possible':''}} · 0–1 km shear {{data.severe.shear1[chosen.i].toFixed(1)}} m/s · deep shear {{data.severe.shear6[chosen.i].toFixed(1)}} m/s · helicity {{data.severe.helicity[chosen.i].toFixed(0)}} m²/s²<br>Heated CAPE {{data.severe.cape[chosen.i].toFixed(0)}} / CIN {{data.severe.cin[chosen.i].toFixed(0)}} J/kg · cap {{data.severe.cap[chosen.i].toFixed(0)}} J/kg {{data.severe.capped[chosen.i]?(data.severe.capBroken[chosen.i]?'(broken)':'(holding)'):'(none)'}} · storm motion ({{data.severe.motionEast[chosen.i].toFixed(1)}}, {{data.severe.motionNorth[chosen.i].toFixed(1)}}) m/s</p><p v-if="data.coupled?.columns">Column ({{data.coupled.columns.config.layer_count}} × {{data.coupled.columns.config.layer_thickness_m}} m): LCL {{data.coupled.columns.lcl[chosen.i]===null?'none':data.coupled.columns.lcl[chosen.i].toFixed(0)+' m'}} · LFC {{data.coupled.columns.lfc[chosen.i]===null?'none':data.coupled.columns.lfc[chosen.i].toFixed(0)+' m'}} · EL {{data.coupled.columns.el[chosen.i]===null?'none':data.coupled.columns.el[chosen.i].toFixed(0)+' m'}}<br>CAPE {{data.coupled.columns.cape[chosen.i].toFixed(0)}} J/kg · CIN {{data.coupled.columns.cin[chosen.i].toFixed(0)}} J/kg · potential {{data.coupled.columns.potential[chosen.i]}} · condensed {{data.coupled.columns.condensed[chosen.i].toFixed(3)}} kg/m²</p><p v-if="data.terrainTemperature && layer==='temperature'">Reference temperature {{(forecast.fields.air_temperature.values[chosen.i]-273.15).toFixed(2)}} °C<br>Terrain correction {{(data.terrainTemperature.values[chosen.i]-forecast.fields.air_temperature.values[chosen.i]).toFixed(2)}} K</p><p v-if="data.terrainDerivatives">Slope {{data.terrainDerivatives.slope_deg[chosen.i].toFixed(2)}}° · Aspect {{data.terrainDerivatives.aspect_deg[chosen.i]===null?'flat / undefined':data.terrainDerivatives.aspect_deg[chosen.i].toFixed(1)+'°'}}</p><p v-if="data.terrain">Elevation {{data.terrain.values[chosen.i].toFixed(2)}} m · {{data.terrain.vertical_reference}}</p><p v-if="layer==='rainfall'">Quality: {{data.rain.quality[chosen.i]}}</p></template><p v-else class="hint">Select a cell in the scene to inspect its value and local coordinates.</p></section>
   <section class="request"><details class="request-fold" :open="requestOpen" @toggle="requestOpen=$event.target.open"><summary title="Build a request for the C++ coupled-wind CLI: grid, time steps, atmosphere, diffusion and pressure systems."><span class="section-label">04 / COUPLED WIND REQUEST</span><small>{{requestOpen?'fold':'unfold'}}</small></summary><p class="hint">Edit the time steps, grid, atmosphere, diffusion and pressure systems, download the request and run <code>terraflux-run-coupled-wind</code>. No physics runs in the browser; checks mirror the solver bounds.</p>
    <div class="request-form">
     <label class="wide">Start time (UTC)<input v-model="coupledForm.start_time_utc"></label>
     <label>Timestep s<input type="number" min="1" v-model.number="coupledForm.timestep_seconds"></label><label>Steps<input type="number" min="1" step="1" v-model.number="coupledForm.steps"></label>
     <label>Snapshot every N steps<input type="number" min="1" step="1" v-model.number="coupledForm.snapshot_every_steps"></label><label>Density mode<select v-model="coupledForm.density_mode"><option v-for="m in DENSITY_MODES" :key="m" :value="m">{{m}}</option></select></label>
     <label>Cells east (nx)<input type="number" min="2" step="1" v-model.number="coupledForm.nx"></label><label>Cells north (ny)<input type="number" min="2" step="1" v-model.number="coupledForm.ny"></label>
     <label>Spacing east m<input type="number" min="1" v-model.number="coupledForm.spacing_east_m"></label><label>Spacing north m<input type="number" min="1" v-model.number="coupledForm.spacing_north_m"></label>
     <label>Anchor latitude °<input type="number" step="0.1" v-model.number="coupledForm.geographic_anchor_latitude_deg"></label><label>Anchor longitude °<input type="number" step="0.1" v-model.number="coupledForm.geographic_anchor_longitude_deg"></label>
     <label>Coriolis mode<select v-model="coupledForm.coriolis_mode"><option v-for="m in CORIOLIS_MODES" :key="m" :value="m">{{m}}</option></select></label><label>Prescribed f 1/s<input type="number" step="1e-5" :disabled="coupledForm.coriolis_mode!=='prescribed'" v-model.number="coupledForm.coriolis_parameter_s"></label>
     <label>Air density kg/m³<input type="number" step="0.001" v-model.number="coupledForm.air_density_kg_m3"></label><label>Friction k 1/s<input type="number" step="1e-6" v-model.number="coupledForm.surface_friction_coefficient_s"></label>
     <label>Temperature diffusion m²/s<input type="number" min="0" v-model.number="coupledForm.temperature_diffusivity_m2_s"></label><label>Humidity diffusion m²/s<input type="number" min="0" v-model.number="coupledForm.humidity_diffusivity_m2_s"></label>
     <label>Momentum diffusion m²/s<input type="number" min="0" v-model.number="coupledForm.momentum_diffusivity_m2_s"></label><label>Scalar boundary<select v-model="coupledForm.scalar_boundary"><option v-for="m in SCALAR_BOUNDARIES" :key="m" :value="m">{{m}}</option></select></label>
     <label>Gradient boundary<select v-model="coupledForm.pressure_gradient_boundary"><option v-for="m in GRADIENT_BOUNDARIES" :key="m" :value="m">{{m}}</option></select></label><label>Background pressure Pa<input type="number" v-model.number="coupledForm.background_pressure_pa"></label>
     <label>Background temperature K<input type="number" step="0.1" v-model.number="coupledForm.background_temperature_k"></label><label>Background humidity kg/kg<input type="number" step="0.001" v-model.number="coupledForm.background_humidity_kg_kg"></label>
    </div>
    <label class="toggle"><input type="checkbox" v-model="coupledForm.column_enabled"> Vertical column diagnostics (layers, cloud base, CAPE)</label>
    <div v-if="coupledForm.column_enabled" class="request-form">
     <label>Layers<input type="number" min="2" step="1" v-model.number="coupledForm.column_layer_count"></label><label>Layer thickness m<input type="number" min="1" v-model.number="coupledForm.column_layer_thickness_m"></label>
     <label>Environment lapse rate K/m<input type="number" step="0.0005" v-model.number="coupledForm.column_lapse_rate_k_m"></label><label>Tropopause height m<input type="number" min="0" v-model.number="coupledForm.column_tropopause_height_m"></label>
     <label>Humidity scale height m<input type="number" min="1" v-model.number="coupledForm.column_humidity_scale_height_m"></label><label>Parcel step m<input type="number" min="1" v-model.number="coupledForm.column_parcel_step_m"></label>
    </div>
    <label v-if="coupledForm.column_enabled" class="toggle"><input type="checkbox" v-model="coupledForm.inversion_enabled"> Temperature inversion (capping layer storing convective energy)</label>
    <div v-if="coupledForm.column_enabled&&coupledForm.inversion_enabled" class="request-form">
     <label>Inversion base m<input type="number" min="0" v-model.number="coupledForm.inversion_base_m"></label><label>Inversion depth m<input type="number" min="1" v-model.number="coupledForm.inversion_depth_m"></label>
     <label>Inversion strength K<input type="number" min="0" step="0.5" v-model.number="coupledForm.inversion_strength_k"></label><label>Lapse rate above K/m<input type="number" step="0.0005" v-model.number="coupledForm.lapse_rate_above_inversion_k_m"></label>
    </div>
    <div v-for="(c,i) in coupledForm.centers" :key="i" class="center-row"><div class="center-head"><strong>{{c.kind==='low'?'L':'H'}} · Pressure system {{i+1}}</strong><button class="text-button" @click="removeCenter(i)">remove</button></div><div class="request-form">
     <label>Kind<select v-model="c.kind"><option value="high">high</option><option value="low">low</option></select></label><label>Radius m<input type="number" min="1" v-model.number="c.radius_m"></label>
     <label>East m<input type="number" v-model.number="c.east_m"></label><label>North m<input type="number" v-model.number="c.north_m"></label>
     <label>Δ pressure Pa<input type="number" v-model.number="c.pressure_anomaly_pa"></label><label>Δ temperature K<input type="number" step="0.1" v-model.number="c.temperature_anomaly_k"></label>
     <label class="wide">Δ specific humidity kg/kg<input type="number" step="0.001" v-model.number="c.humidity_anomaly_kg_kg"></label>
    </div></div>
    <button class="text-button" @click="addCenter">+ add pressure system</button>
    <div v-for="(a,i) in coupledForm.airmasses" :key="'a'+i" class="center-row"><div class="center-head"><strong>Air mass {{i+1}} (temperature / humidity anomaly)</strong><button class="text-button" @click="removeAirmass(i)">remove</button></div><div class="request-form">
     <label>East m<input type="number" v-model.number="a.east_m"></label><label>North m<input type="number" v-model.number="a.north_m"></label>
     <label>Radius m<input type="number" min="1" v-model.number="a.radius_m"></label><label>Δ temperature K<input type="number" step="0.1" v-model.number="a.temperature_anomaly_k"></label>
     <label class="wide">Δ specific humidity kg/kg<input type="number" step="0.001" v-model.number="a.humidity_anomaly_kg_kg"></label>
    </div></div>
    <button class="text-button" @click="addAirmass">+ add air mass (warm sector / cold pool)</button>
    <label class="toggle"><input type="checkbox" v-model="coupledForm.cloud_enabled" :disabled="!coupledForm.column_enabled"> Cloud formation (fronts, convection, thunderstorms; needs the column)</label>
    <div v-if="coupledForm.cloud_enabled" class="request-form">
     <label>Diurnal heating amplitude K<input type="number" min="0" step="0.5" v-model.number="coupledForm.cloud_heating_amplitude_k"></label><label>Heating phase s (sunrise offset)<input type="number" step="600" v-model.number="coupledForm.cloud_heating_phase_seconds"></label>
     <label v-for="[key,label] in CLOUD_CONFIG_KEYS" :key="key">{{label}}<input type="number" step="any" v-model.number="coupledForm.cloud[key]"></label>
    </div>
    <label v-if="coupledForm.cloud_enabled" class="toggle"><input type="checkbox" v-model="coupledForm.severe_enabled"> Severe convection (tornado parameter from the inversion, low-level shear and helicity)</label>
    <label v-if="coupledForm.cloud_enabled" class="toggle"><input type="checkbox" v-model="coupledForm.precip_enabled"> Precipitation outcomes (rain, snow, sleet, hail, thunderstorms)</label>
    <div v-if="coupledForm.cloud_enabled&&coupledForm.precip_enabled" class="request-form">
     <label v-for="[key,label] in PRECIP_CONFIG_KEYS" :key="key">{{label}}<input type="number" step="any" v-model.number="coupledForm.precip[key]"></label>
    </div>
    <label class="toggle"><input type="checkbox" v-model="coupledForm.orography_enabled"> Orography: mountain ridges (orientation!), basins, foehn, blocking, valley cold pools</label>
    <template v-if="coupledForm.orography_enabled">
     <div class="request-form"><label>Base elevation m<input type="number" v-model.number="coupledForm.terrain_base_elevation_m"></label><label v-for="[key,label] in OROGRAPHY_KEYS" :key="key">{{label}}<input type="number" step="any" v-model.number="coupledForm.orography[key]"></label></div>
     <div v-for="(r,i) in coupledForm.ridges" :key="'ridge'+i" class="center-row"><div class="center-head"><strong>Ridge {{i+1}} · {{r.orientation_deg%180===0?'north–south (blocks zonal flow)':Math.abs(r.orientation_deg%180)===90?'east–west (blocks north–south exchange)':r.orientation_deg+'°'}}</strong><button class="text-button" @click="removeRidge(i)">remove</button></div><div class="request-form">
      <label>Axis orientation ° (0 = N–S, 90 = E–W)<input type="number" step="15" v-model.number="r.orientation_deg"></label><label>Height m<input type="number" min="0" v-model.number="r.height_m"></label>
      <label>Centre east m<input type="number" v-model.number="r.center_east_m"></label><label>Centre north m<input type="number" v-model.number="r.center_north_m"></label>
      <label>Half width m<input type="number" min="1" v-model.number="r.half_width_m"></label><label>Length m<input type="number" min="1" v-model.number="r.length_m"></label>
     </div></div>
     <button class="text-button" @click="addRidge">+ add ridge</button>
     <div v-for="(b,i) in coupledForm.basins" :key="'basin'+i" class="center-row"><div class="center-head"><strong>Basin / valley {{i+1}}</strong><button class="text-button" @click="removeBasin(i)">remove</button></div><div class="request-form">
      <label>Centre east m<input type="number" v-model.number="b.center_east_m"></label><label>Centre north m<input type="number" v-model.number="b.center_north_m"></label>
      <label>Depth m<input type="number" min="0" v-model.number="b.depth_m"></label><label>Radius m<input type="number" min="1" v-model.number="b.radius_m"></label>
     </div></div>
     <button class="text-button" @click="addBasin">+ add basin</button>
    </template>
    <label class="toggle"><input type="checkbox" v-model="coupledForm.surface_enabled"> Surface: straight coastline and sea-surface temperature</label>
    <div v-if="coupledForm.surface_enabled" class="request-form">
     <label>Coast position east m<input type="number" v-model.number="coupledForm.coast_east_m"></label><label>Land side<select v-model="coupledForm.land_side"><option value="west">west</option><option value="east">east</option></select></label>
     <label>Sea-surface temperature K<input type="number" step="0.1" v-model.number="coupledForm.sea_surface_temperature_k"></label><label>SST gradient north K/m<input type="number" step="1e-6" v-model.number="coupledForm.sst_gradient_north_k_per_m"></label>
    </div>
    <label v-if="coupledForm.surface_enabled&&coupledForm.column_enabled" class="toggle"><input type="checkbox" v-model="coupledForm.storms_enabled"> Tropical cyclones (genesis, intensity, Fujiwhara, merger, landfall) with default storm physics</label>
    <template v-if="coupledForm.surface_enabled&&coupledForm.column_enabled&&coupledForm.storms_enabled">
     <div v-for="(x,i) in coupledForm.storm_seeds" :key="'seed'+i" class="center-row"><div class="center-head"><strong>Storm seed {{i+1}}</strong><button class="text-button" @click="removeSeed(i)">remove</button></div><div class="request-form">
      <label>East m<input type="number" v-model.number="x.east_m"></label><label>North m<input type="number" v-model.number="x.north_m"></label>
      <label>Max wind m/s<input type="number" min="1" v-model.number="x.max_wind_m_s"></label><label>Radius of max wind m<input type="number" min="1" v-model.number="x.radius_max_wind_m"></label>
     </div></div>
     <button class="text-button" @click="addSeed">+ add storm seed</button>
    </template>
    <ul class="report"><li v-for="e in coupledReport.errors" :key="e" class="report-error">✕ {{e}}</li><li v-for="w in coupledReport.warnings" :key="w" class="report-warn">△ {{w}}</li><li v-if="!coupledReport.errors.length" class="report-ok">✓ Request passes the configuration checks</li></ul>
    <p v-if="!coupledReport.errors.length" class="hint">f {{coupledReport.estimates.coriolis_parameter_s?.toExponential(3)}} 1/s · inertial period {{fmt(coupledReport.estimates.inertial_period_h,1)}} h · friction time {{fmt(coupledReport.estimates.friction_time_h,1)}} h · cross-isobar angle {{fmt(coupledReport.estimates.cross_isobar_angle_deg,1)}}°<br>Δt(|f|+k) {{fmt(coupledReport.estimates.coriolis_friction_number,3)}} · momentum diffusion number {{fmt(coupledReport.estimates.momentum_diffusion_number,3)}} · scalar stability estimate at spin-up peak {{fmt(coupledReport.estimates.scalar_stability_estimate,2)}}<br>Balanced wind ≈ {{fmt(coupledReport.estimates.balanced_speed_estimate_m_s,1)}} m/s · peak ≈ {{fmt(coupledReport.estimates.peak_speed_estimate_m_s,1)}} m/s · upwind numerical diffusion ≈ {{fmt(coupledReport.estimates.numerical_diffusivity_estimate_m2_s,0)}} m²/s<template v-if="coupledReport.estimates.column_top_m"><br>Column top {{fmt(coupledReport.estimates.column_top_m/1000,1)}} km</template></p>
    <div class="comparison-switch"><button :disabled="coupledReport.errors.length>0" @click="downloadCoupledRequest">⇩ Download request JSON</button><button v-if="data.coupled" @click="useLoadedCoupledSettings">Use loaded run's settings</button><button @click="resetCoupledForm">Reset to example</button></div>
    <p v-if="coupledNote" class="hint">{{coupledNote}}</p>
   </details></section>
  </aside><article><div class="scene-head"><div><span class="eyebrow">FIELD EXPLORER</span><h2>{{layer==='temperature'?(adjustedTemperature?'Terrain-adjusted temperature':'Air temperature'):layer==='wind'?'Wind speed':layer==='terrain'?'Terrain elevation':layer==='slope'?'Terrain slope':layer==='aspect'?'Downhill aspect':layer==='water'?'Surface water depth':layer==='soil'?'Soil water storage':layer==='cloud'?'Cloud cover':layer==='pressure'?'Sea-level pressure':layer==='humidity'?'Relative humidity':layer==='density'?'Air density':layer==='moisture'?'Specific humidity':layer==='cape'?'Convective available potential energy':layer==='cloudbase'?'Cloud base (lifting condensation level)':layer==='cloudtop'?'Equilibrium level':layer==='clouds'?'Cloud formation · fronts and convection':layer==='precip'?'Precipitation rate at the ground':layer==='accum'?'Precipitation accumulated over the snapshot interval':layer==='stormwind'?'Tropical cyclone wind field':layer==='mpi'?'Maximum potential intensity':layer==='gpi'?'Genesis potential index':layer==='surge'?'Storm surge estimate':layer==='stp'?'Significant tornado parameter':layer==='helicity'?'Storm-relative helicity':layer==='lifting'?'Orographic lifting (up-slope positive)':layer==='blocked'?'Froude blocking of the cross-barrier flow':layer==='foehn'?'Foehn warming on the lee':layer==='coldpool'?'Cold-air pool deficit':layer==='oroprecip'?'Orographic precipitation rate':layer==='valley'?'Valley depth':layer==='discharge'?'River discharge':layer==='surfacewater'?'Surface and floodplain water':layer==='saturation'?'Soil saturation':layer==='watertable'?'Water-table depth below ground':layer==='snowpack'?'Snowpack water equivalent':layer==='erosion'?'Cumulative erosion':layer==='deposition'?'Cumulative deposition':layer==='stability'?'Slope factor of safety':layer==='floodclass'?'Flood hazard class':layer==='current'?'Ocean current speed':layer==='surfacesalinity'?'Surface salinity':layer==='salinity'?'Upper-ocean layer salinity':layer==='sst'?'Upper-ocean layer temperature':layer==='thermocline'?'Thermocline depth (layer thickness)':layer==='freshwater'?'Surface freshwater fraction':layer==='sinking'?'Deep-water formation rate':layer==='oceansst'?'Sea-surface temperature (top layer)':layer==='mld'?'Ocean mixed-layer depth':layer==='netheat'?'Net air–sea heat flux (into the ocean)':layer==='latent'?'Latent heat flux (evaporative cooling)':layer==='evaporation'?'Evaporation from the sea':layer==='searain'?'Rain on sea and land':layer==='coastalstore'?'Coastal runoff store':layer==='icethickness'?'Greenland ice thickness':layer==='icesmb'?'Greenland surface mass balance':layer==='icemelt'?'Greenland surface melt':layer==='seaice'?'Sea-ice concentration':layer==='seaicethick'?'Sea-ice thickness':layer==='oxygen'?'Surface dissolved-oxygen capacity':layer==='coastlost'?'Land lost to the sea':layer==='coastyear'?'Year the land is lost':layer==='coaststorm'?'Design-storm flood depth':layer==='coastinundation'?'Permanent inundation':layer==='coastfrequency'?'Today\'s 100-year flood: now every … years':layer==='coastsetup'?'Wind setup of the design storm':layer==='coastsubsidence'?'Land subsidence':layer==='coastpopulation'?'Population density':'Rainfall accumulation'}}</h2></div><div class="view-switch"><button :class="{selected:view==='field'}" @click="view='field'">Field explorer</button><button :class="{selected:view==='map'}" :disabled="!data.coupled" @click="view='map'">Weather map</button><button :class="{selected:view==='water'}" :disabled="!data.hydrology" @click="view='water'">Catchment</button><button :class="{selected:view==='hazards'}" :disabled="!data.hydrology" @click="view='hazards'">Hazards</button><button :class="{selected:view==='ocean'}" :disabled="!data.ocean" @click="view='ocean'">Ocean streams</button><button :class="{selected:view==='polar'}" :disabled="!data.polar" @click="view='polar'">Polar melt</button><button :class="{selected:view==='coast'}" :disabled="!data.coast" @click="view='coast'" title="Sea-level rise on the coast: land lost, storm floods, defences, rivers and islands.">Sea level &amp; coasts</button><button class="reset" @click="reset">↺ Reset view</button></div></div><div class="viewport" ref="host" aria-label="Interactive 3D weather grid"><div v-if="fallback" class="fallback-grid" :style="{gridTemplateColumns:`repeat(${grid.nx},1fr)`}"><button v-for="(value,i) in values" :key="i" :aria-label="`Cell ${i}: ${value===null?'no data':value.toFixed(2)} ${unit}`" :style="{gridRow:grid.ny-Math.floor(i/grid.nx),gridColumn:i%grid.nx+1,background:view!=='field'?mapCellStyles[i]:value===null?'#283b49':layer==='clouds'?CLOUD_TYPES[value].color:`hsl(${hue(value)} ${layer==='cloud'?15:70}% ${layer==='cloud'?18+value*.72:50}%)`}" @click="selected=i"></button></div><svg v-if="fallback && data.atmosphere" class="systems-map" viewBox="0 0 100 100" preserveAspectRatio="none" aria-label="Synthetic cloud and weather-system overlay"><template v-if="cloudsEnabled"><ellipse v-for="(c,i) in data.atmosphere.cloud" :key="'cloud'+i" v-show="i%3===0 && c>.35" :cx="((i%grid.nx)+.5)/grid.nx*100" :cy="(1-(Math.floor(i/grid.nx)+.5)/grid.ny)*100" :rx="2.1" :ry="1.7" fill="#e9f5ff" :opacity="c*.32"/></template><template v-if="systemsEnabled"><template v-for="(s,i) in data.atmosphere.systems" :key="i"><polyline v-if="s.kind==='cold_front'" :points="s.points.map(([u,v])=>`${u*100},${(1-v)*100}`).join(' ')" fill="none" stroke="#85ccff" stroke-width=".7" stroke-dasharray="2 1"/><text v-else :x="s.u*100" :y="(1-s.v)*100" :fill="s.kind==='low'?'#ffb39c':'#c5e9ff'" font-size="7" font-weight="bold" text-anchor="middle">{{s.kind==='low'?'L':'H'}}</text></template></template></svg><svg v-if="fallback && view==='map'" class="systems-map" viewBox="0 0 100 100" preserveAspectRatio="none" aria-label="Weather map overlays"><template v-for="level in isobarLines" :key="level.level_pa"><polyline v-for="(line,li) in level.lines" :key="li" :points="line.map(([u,v])=>`${u*100},${(1-v)*100}`).join(' ')" fill="none" :stroke="Math.round(level.level_hpa)%(mapLayers.isobarIntervalHpa*2)===0?'#f3f7f9':'#a9bcc6'" :stroke-width="Math.round(level.level_hpa)%(mapLayers.isobarIntervalHpa*2)===0?.5:.3"/><text v-if="Math.round(level.level_hpa)%(mapLayers.isobarIntervalHpa*2)===0&&level.lines[0]" :x="level.lines[0][0][0]*100" :y="(1-level.lines[0][0][1])*100" font-size="2.6" fill="#f3f7f9">{{Math.round(level.level_hpa)}}</text></template><template v-if="mapLayers.fronts&&data.clouds"><template v-for="(t,i) in data.clouds.frontType" :key="'f'+i"><rect v-if="t!=='none'" :x="(i%grid.nx)/grid.nx*100" :y="(1-(Math.floor(i/grid.nx)+1)/grid.ny)*100" :width="100/grid.nx" :height="100/grid.ny" :fill="FRONT_COLORS[t]" opacity=".5"/></template></template><template v-if="mapLayers.symbols&&data.precipitation"><template v-for="(t,i) in data.precipitation.type" :key="'p'+i"><text v-if="t!=='none'&&(i%grid.nx)%symbolStride===0&&Math.floor(i/grid.nx)%symbolStride===0" :x="((i%grid.nx)+.5)/grid.nx*100" :y="(1-(Math.floor(i/grid.nx)+.3)/grid.ny)*100" font-size="2.8" text-anchor="middle" :fill="data.precipitation.phase[i]==='solid'?'#ffffff':'#bfe0ff'">{{precipitationTypeInfo(t).symbol}}</text></template></template><template v-if="mapLayers.storms&&data.storms"><template v-for="s in data.storms.list" :key="'st'+s.id"><polyline v-if="s.track.length>1" :points="s.track.map(([e,n])=>`${(e-grid.origin_east_m)/(grid.nx*grid.spacing_east_m)*100},${(1-(n-grid.origin_north_m)/(grid.ny*grid.spacing_north_m))*100}`).join(' ')" fill="none" stroke="#ffffff" stroke-width=".4" opacity=".7"/><circle :cx="(s.east_m-grid.origin_east_m)/(grid.nx*grid.spacing_east_m)*100" :cy="(1-(s.north_m-grid.origin_north_m)/(grid.ny*grid.spacing_north_m))*100" :r="Math.max(1.5,s.radius_max_wind_m/(grid.nx*grid.spacing_east_m)*100)" fill="none" :stroke="categoryInfo(s.category).color" stroke-width=".8"/><text :x="(s.east_m-grid.origin_east_m)/(grid.nx*grid.spacing_east_m)*100" :y="(1-(s.north_m-grid.origin_north_m)/(grid.ny*grid.spacing_north_m))*100-2.5" font-size="3" text-anchor="middle" :fill="categoryInfo(s.category).color">{{categoryInfo(s.category).short}}</text></template><text v-for="(e,i) in visibleEvents.filter(e=>['landfall','merger','genesis'].includes(e.kind))" :key="'ev'+i" :x="(e.east_m-grid.origin_east_m)/(grid.nx*grid.spacing_east_m)*100" :y="(1-(e.north_m-grid.origin_north_m)/(grid.ny*grid.spacing_north_m))*100+1" font-size="3" text-anchor="middle" :fill="e.kind==='landfall'?'#ff5c5c':'#ffffff'">{{e.kind==='landfall'?'✖':e.kind==='merger'?'⊕':'✦'}}</text></template><template v-if="data.orography"><template v-for="(b,i) in data.orography.foehn" :key="'fo'+i"><text v-if="mapLayers.foehn&&b" :x="((i%grid.nx)+.5)/grid.nx*100" :y="(1-(Math.floor(i/grid.nx)+.4)/grid.ny)*100" font-size="3" text-anchor="middle" fill="#ff8c42">F</text></template><template v-for="(b,i) in data.orography.coldPoolFlag" :key="'cp'+i"><text v-if="mapLayers.coldPools&&b" :x="((i%grid.nx)+.5)/grid.nx*100" :y="(1-(Math.floor(i/grid.nx)+.4)/grid.ny)*100" font-size="3" text-anchor="middle" fill="#dff3ff">❄</text></template></template><template v-if="mapLayers.tornado&&data.severe"><template v-for="(b,i) in data.severe.possible" :key="'t'+i"><text v-if="b" :x="((i%grid.nx)+.5)/grid.nx*100" :y="(1-(Math.floor(i/grid.nx)+.5)/grid.ny)*100" font-size="3.2" text-anchor="middle">🌪</text></template></template><template v-if="mapLayers.hazards&&data.precipitation"><template v-for="(b,i) in data.precipitation.lightning" :key="'h'+i"><text v-if="b" :x="((i%grid.nx)+.5)/grid.nx*100" :y="(1-(Math.floor(i/grid.nx)+.7)/grid.ny)*100" font-size="3" text-anchor="middle" fill="#ffd166">{{data.precipitation.hail[i]>0?'⚡◆':'⚡'}}</text></template></template></svg><svg v-if="fallback && view==='field' && data.clouds && frontOverlay" class="systems-map" viewBox="0 0 100 100" preserveAspectRatio="none" aria-label="Front overlay"><template v-for="(t,i) in data.clouds.frontType" :key="i"><rect v-if="t!=='none'" :x="(i%grid.nx)/grid.nx*100" :y="(1-(Math.floor(i/grid.nx)+1)/grid.ny)*100" :width="100/grid.nx" :height="100/grid.ny" :fill="FRONT_COLORS[t]" opacity=".55"/></template><template v-for="(s,i) in data.clouds.thunderstorm" :key="'s'+i"><text v-if="s" :x="((i%grid.nx)+.5)/grid.nx*100" :y="(1-(Math.floor(i/grid.nx)+.3)/grid.ny)*100" font-size="3" text-anchor="middle" fill="#ffd166">⚡</text></template></svg><svg v-if="fallback && data.surfaceWater?.outlets?.length" class="systems-map" viewBox="0 0 100 100" preserveAspectRatio="none" aria-label="Configured surface outlet locations"><circle v-for="(o,i) in data.surfaceWater.outlets" :key="i" :cx="(o.x+.5)/grid.nx*100" :cy="(1-(o.y+.5)/grid.ny)*100" r="1.6" fill="#ffa15c" stroke="#fff2e6" stroke-width=".4"/></svg><div class="scene-note">{{fallback?'2D FALLBACK / NORTH UP':'NORTH −Z / EAST +X'}}<br><span>{{fallback?'Color encodes field value · select a cell':data.terrain&&(terrainEnabled||layer==='terrain')?'Height: relative terrain · color: selected field':'Height encodes field value · flat reference surface'}}</span></div><div v-if="view==='map'" class="cloud-key map-key"><span v-if="mapLayers.base!=='none'"><i :style="{background:mapLayers.base==='temperature'?'linear-gradient(90deg,hsl(223 55% 30%),hsl(11 55% 42%))':'linear-gradient(90deg,hsl(260 35% 26%),hsl(140 35% 44%))'}"></i>{{mapLayers.base==='temperature'?`Temperature ${(temperatureRange[0]-273.15).toFixed(0)}–${(temperatureRange[1]-273.15).toFixed(0)} °C`:`Pressure ${(pressureRange[0]/100).toFixed(0)}–${(pressureRange[1]/100).toFixed(0)} hPa`}}</span><span v-if="mapLayers.isobars">━ isobars {{mapLayers.isobarIntervalHpa}} hPa (bright = {{mapLayers.isobarIntervalHpa*2}} hPa)</span><template v-if="mapLayers.precipitation&&data.precipitation"><span v-for="r in [0.5,3,15,40]" :key="r"><i :style="{background:rateColor(r)}"></i>{{r}} mm/h</span></template><template v-if="mapLayers.clouds&&data.clouds"><span v-for="t in CLOUD_TYPES.slice(1)" :key="t.key"><i :style="{background:t.color}"></i>{{t.abbreviation}}</span></template><span v-if="mapLayers.fronts&&data.clouds"><i style="background:#4da3ff"></i>cold <i style="background:#ff6b6b"></i>warm <i style="background:#c792ea"></i>stationary</span><template v-if="(mapLayers.storms||mapLayers.stormWind)&&data.storms"><span v-for="c in CATEGORIES" :key="c.key"><i :style="{background:c.color}"></i>{{c.short}} {{c.label}}</span></template><span v-if="mapLayers.surge&&data.storms"><i style="background:#00e5ff"></i>storm surge</span><template v-if="mapLayers.tornado&&data.severe"><span><i style="background:#ffe066"></i>STP low <i style="background:#ff7f50"></i>moderate <i style="background:#c724b1"></i>significant</span></template><template v-if="data.orography"><span v-if="mapLayers.lifting"><i style="background:#3da5ff"></i>up-slope <i style="background:#ff8c42"></i>descent</span><span v-if="mapLayers.coldPools"><i style="background:#9ad7ff"></i>cold pool ❄</span><span v-if="mapLayers.foehn">F foehn</span><span v-if="mapLayers.blocking"><i style="background:#f0e68c"></i>blocked flow</span></template></div><div v-else-if="layer==='clouds'" class="cloud-key"><span v-for="t in CLOUD_TYPES" :key="t.key"><i :style="{background:t.color}"></i>{{t.abbreviation}} {{t.label}}</span></div><div v-else class="legend"><span>{{range[0].toFixed(1)}} {{unit}}</span><div :style="layer==='aspect'?{background:'linear-gradient(90deg,red,yellow,lime,cyan,blue,magenta,red)'}:['rainfall','water','soil'].includes(layer)?{background:'linear-gradient(90deg,#2675cc,#26ccb2)'}:{}"></div><span>{{range[1].toFixed(1)}} {{unit}}</span></div><div v-if="layer==='aspect'" class="aspect-key">0° N · 90° E · 180° S · 270° W · gray = flat</div><div class="gestures">{{fallback?'SELECT A CELL TO INSPECT':'DRAG TO ORBIT · SCROLL TO ZOOM · CLICK TO INSPECT'}}</div></div><div v-if="snapshots.length>1" class="timeline"><div class="playback"><button @click="seek(frameIndex-1)" :disabled="frameIndex===0" aria-label="Previous frame">‹</button><button @click="togglePlayback">{{playing?'Pause':'Play'}}</button><button @click="seek(frameIndex+1)" :disabled="frameIndex===snapshots.length-1" aria-label="Next frame">›</button><span>Frame {{frameIndex+1}} / {{snapshots.length}} · {{playbackLabel}}</span></div><input aria-label="Timeline frame" type="range" min="0" :max="snapshots.length-1" :value="frameIndex" @input="seek($event.target.value)"><p>{{data.orography?`Engine orography · ${data.orography.foehnCells} foehn cells · ${data.orography.poolCells} cold pools · surface ${(data.orography.tendency*3600).toFixed(2)} K/h`:data.storms?`${data.storms.synthetic?'Synthetic mock':'Engine'} storms · ${data.storms.list.length} active · events so far: ${visibleEvents.map(e=>e.kind).join(', ')||'none'}`+(data.severe?` · tornado possible in ${data.severe.possibleCells} cells`:''):data.precipitation?`${data.precipitation.synthetic?'Synthetic mock':'Engine'} outcomes · ${data.precipitation.precipitating} precipitating cells · ${data.precipitation.lightningCells} thunderstorms · ${data.precipitation.hailCells} hail · ${data.precipitation.snowCells} snow · max ${data.precipitation.maxRate.toFixed(1)} mm/h`:data.clouds?`${data.clouds.synthetic?'Synthetic mock':'Engine'} cloud snapshots · heating ${data.clouds.heating.toFixed(1)} K · ${data.clouds.cloudy} cloudy cells · ${data.clouds.storms} thunderstorm cells · ${data.clouds.fronts} frontal cells`:data.coupled?`Coupled engine snapshots · fixed color scale · pressure static · scalar stability number ${data.coupled.stability.toFixed(2)} · supersaturated cells ${data.coupled.supersaturated}`:data.atmosphere?'Synthetic regional snapshots · fixed color scale · no coupling to local engine physics':'Discrete solver snapshots · fixed color scale · rainfall accumulates from the start · unavailable at time zero'}}</p></div><p v-if="layer==='rainfall' && data.rain" class="rain-interval">Accumulation interval: {{data.rain.period_start_utc.replace('T',' ').replace('Z',' UTC')}} → {{data.rain.valid_time_utc.replace('T',' ').replace('Z',' UTC')}}</p><p v-if="['water','soil'].includes(layer) && data.surfaceWater" class="rain-interval">Surface {{data.surfaceWater.stored_volume_m3.toFixed(2)}} m³ · Soil {{data.surfaceWater.soil_volume_m3.toFixed(2)}} m³ · Rain input {{data.surfaceWater.cumulative_rainfall_volume_m3.toFixed(2)}} m³ · Evaporated {{data.surfaceWater.evaporated_volume_m3.toFixed(2)}} m³ · Drained {{data.surfaceWater.drained_volume_m3.toFixed(2)}} m³ · Discharged {{data.surfaceWater.discharged_volume_m3.toFixed(2)}} m³ · Balance error {{data.surfaceWater.balance_error_m3.toExponential(2)}} m³<br>{{data.surfaceWater.boundary==='configured_outlets'?'Configured surface outlets':'Closed boundaries'}} · unknown rainfall cells are impermeable masks · prototype routing<br>Step {{data.surfaceWater.parameters.timestep_seconds}} s · Infiltration {{(data.surfaceWater.parameters.infiltration_rate_m_s*3600000).toFixed(2)}} mm/h · Evaporation {{(data.surfaceWater.parameters.evaporation_rate_m_s*3600000).toFixed(2)}} mm/h · Drainage {{(data.surfaceWater.parameters.drainage_rate_m_s*3600000).toFixed(2)}} mm/h<span v-if="data.surfaceWater.soil_capacity_m!==null"> · soil capacity {{data.surfaceWater.soil_capacity_m*1000}} mm</span></p><section v-if="comparisonFrames" class="comparison"><div class="section-label">SCENARIO COMPARISON · SAME FORCING / TIME</div><div class="comparison-switch"><button @click="exportComparison">Export all frames (CSV)</button><button :class="{selected:comparisonView==='baseline'}" @click="comparisonView='baseline'">Show baseline</button><button :class="{selected:comparisonView==='variant'}" @click="comparisonView='variant'">Show {{comparisonName}}</button></div><p>Viewing {{comparisonView==='baseline'?'baseline':comparisonName}} · Δ = variant − baseline · volumes in m³</p><table><thead><tr><th>Metric</th><th>Baseline</th><th>{{comparisonName}}</th><th>Δ</th></tr></thead><tbody><tr v-for="row in comparisonRows" :key="row.label"><th>{{row.label}}</th><td>{{row.baseline.toFixed(2)}}</td><td>{{row.variant.toFixed(2)}}</td><td>{{row.delta>=0?'+':''}}{{row.delta.toFixed(2)}}</td></tr></tbody></table><div class="comparison-chart"><small>SURFACE STORAGE OVER TIME · full timeline, shared scale<br>Green = baseline · Blue = variant · dashed line = selected time</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Surface water volume comparison"><polyline :points="chartPath(snapshots)" fill="none" stroke="#b1d9a4" stroke-width=".6"/><polyline :points="chartPath(comparisonFrames)" fill="none" stroke="#75bbfa" stroke-width=".6"/><line :x1="frameIndex/(snapshots.length-1)*100" :x2="frameIndex/(snapshots.length-1)*100" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>0 → {{snapshots.at(-1).forecast.elapsed_seconds/60}} minutes · 0–{{chartMaximum.toFixed(0)}} m³</small></div><p>Baseline infiltration {{(snapshots[0].surfaceWater.parameters.infiltration_rate_m_s*3600000).toFixed(2)}} mm/h · Variant {{(comparisonFrames[0].surfaceWater.parameters.infiltration_rate_m_s*3600000).toFixed(2)}} mm/h</p></section><section v-if="outletSeries.length" class="comparison outlet-report"><div class="section-label">SURFACE OUTLET DISCHARGE</div><p>Orange markers identify configured boundary outlets. Discharged water leaves the modeled domain and remains in the mass budget.</p><div class="outlet-charts"><div class="comparison-chart"><small>CUMULATIVE DISCHARGE · m³</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Cumulative outlet discharge"><polyline :points="outletPath('cumulative_m3',outletVolumeMax)" fill="none" stroke="#ffb77a" stroke-width=".7"/><line :x1="outletTimePosition" :x2="outletTimePosition" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>0–{{outletVolumeMax.toFixed(1)}} m³ · 0–{{visibleFrames.at(-1).forecast.elapsed_seconds/60}} min</small></div><div class="comparison-chart"><small>INTERVAL-MEAN DISCHARGE · m³/s</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Interval mean outlet discharge"><polyline :points="outletPath('mean_rate_m3_s',outletRateMax)" fill="none" stroke="#75bbfa" stroke-width=".7"/><line :x1="outletTimePosition" :x2="outletTimePosition" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>0–{{outletRateMax.toFixed(2)}} m³/s · averages between snapshots</small></div></div><p>Selected time: discharged {{outletSeries[frameIndex].cumulative_m3.toFixed(2)}} m³ · interval mean {{outletSeries[frameIndex].mean_rate_m3_s===null?'no preceding interval':outletSeries[frameIndex].mean_rate_m3_s.toFixed(3)+' m³/s'}}</p></section><div class="metrics extra-metrics"><div><small>DOMAIN AREA</small><strong>{{metrics.area_km2.toLocaleString()}} <em>km²</em></strong></div><div v-if="!data.coast"><small>TEMPERATURE MIN / MEAN / MAX</small><strong class="date">{{metrics.temperature_min_c.toFixed(1)}} / {{metrics.temperature_mean_c.toFixed(1)}} / {{metrics.temperature_max_c.toFixed(1)}} °C</strong></div><div v-if="!data.coast"><small>WIND MEAN / MAX</small><strong class="date">{{metrics.wind_mean_m_s.toFixed(1)}} / {{metrics.wind_max_m_s.toFixed(1)}} m/s</strong></div><template v-if="data.atmosphere"><div><small>MEAN CLOUD FRACTION</small><strong>{{metrics.cloud_pct.toFixed(1)}} <em>%</em></strong></div><div><small>PRESSURE MIN / MAX</small><strong class="date">{{metrics.pressure_min_hpa.toFixed(1)}} / {{metrics.pressure_max_hpa.toFixed(1)}} hPa</strong></div><div><small>MEAN RELATIVE HUMIDITY</small><strong>{{metrics.humidity_mean_pct.toFixed(1)}} <em>%</em></strong></div></template><template v-if="data.rain"><div><small>RAINFALL COVERAGE</small><strong>{{metrics.rain_coverage_pct.toFixed(1)}} <em>%</em></strong></div><div><small>MEAN RAIN · COVERED CELLS</small><strong>{{metrics.rain_mean_mm?.toFixed(2)??'Unknown'}} <em>mm</em></strong></div></template><template v-if="data.surfaceWater"><div><small>WET AREA · DEPTH &gt; 0.1 MM</small><strong>{{metrics.wet_area_km2.toFixed(2)}} <em>km²</em></strong></div><div><small>MAX SURFACE WATER</small><strong>{{metrics.water_max_mm?.toFixed(2)}} <em>mm</em></strong></div><div><small>MEAN SOIL CAPACITY USED</small><strong>{{metrics.soil_fill_pct?.toFixed(1)??'Unknown'}} <em>%</em></strong></div></template></div><div v-if="orographyMetrics" class="metrics extra-metrics"><div><small>FOEHN CELLS · MAX WARMING</small><strong class="date">{{orographyMetrics.foehn_cells}} · +{{orographyMetrics.max_foehn_warming_k.toFixed(1)}} K</strong></div><div><small>COLD POOLS · MAX DEFICIT</small><strong class="date">{{orographyMetrics.cold_pool_cells}} · −{{orographyMetrics.max_cold_pool_k.toFixed(1)}} K</strong></div><div><small>RISING / SINKING AIR</small><strong class="date">{{orographyMetrics.rising_pct.toFixed(0)}} % / {{orographyMetrics.sinking_pct.toFixed(0)}} %</strong></div><div><small>MAX BLOCKED · OROGRAPHIC RAIN</small><strong class="date">{{(orographyMetrics.max_blocked_fraction*100).toFixed(0)}} % · {{orographyMetrics.max_precipitation_rate.toFixed(1)}} mm/h</strong></div><div><small>RIDGE ORIENTATION</small><strong class="date">{{orographyMetrics.orientation_dominant_deg===null?'—':orographyMetrics.orientation_dominant_deg.toFixed(0)+'° (0 = N–S, 90 = E–W)'}}</strong></div><div><small>SURFACE TENDENCY</small><strong class="date">{{orographyMetrics.surface_tendency_k_h>=0?'+':''}}{{orographyMetrics.surface_tendency_k_h.toFixed(2)}} K/h {{orographyMetrics.surface_tendency_k_h<0?'(night)':orographyMetrics.surface_tendency_k_h>0?'(day)':''}}</strong></div></div><div v-if="hydrologyMetrics" class="metrics extra-metrics"><div><small>PEAK DISCHARGE · FLOODED AREA</small><strong class="date">{{hydrologyMetrics.max_discharge_m3_s.toFixed(1)}} m³/s · {{hydrologyMetrics.flooded_area_km2.toFixed(0)}} km²</strong></div><div><small>FLOOD CLASSES L / M / H / X</small><strong class="date">{{hydrologyMetrics.class_cells.low}} / {{hydrologyMetrics.class_cells.medium}} / {{hydrologyMetrics.class_cells.high}} / {{hydrologyMetrics.class_cells.extreme}}</strong></div><div><small>LANDSLIDES · DEBRIS</small><strong class="date">{{hydrologyMetrics.landslides_total}} ({{hydrologyMetrics.landslides_now}} now) · {{(hydrologyMetrics.landslide_volume_m3/1000).toFixed(0)}} ×10³ m³</strong></div><div><small>SEDIMENT YIELD · MAX EROSION</small><strong class="date">{{hydrologyMetrics.sediment_yield_t.toFixed(0)}} t · {{hydrologyMetrics.max_erosion_mm.toFixed(2)}} mm</strong></div><div><small>RAINING · SOIL SATURATION</small><strong class="date">{{hydrologyMetrics.raining_pct.toFixed(0)}} % · {{(hydrologyMetrics.mean_saturation*100).toFixed(0)}} %</strong></div><div><small>RUNOFF RATIO · WARNINGS</small><strong class="date">{{hydrologyMetrics.runoff_ratio===null?'—':(hydrologyMetrics.runoff_ratio*100).toFixed(0)+' %'}} · {{hydrologyMetrics.threshold_cells}} cells</strong></div><div><small>STORES · hm³ (snow / surface / soil / gw / rivers / lakes)</small><strong class="date">{{(hydrologyMetrics.storage.snow/1e6).toFixed(1)}} / {{(hydrologyMetrics.storage.surface/1e6).toFixed(1)}} / {{(hydrologyMetrics.storage.soil/1e6).toFixed(0)}} / {{(hydrologyMetrics.storage.groundwater/1e6).toFixed(0)}} / {{(hydrologyMetrics.storage.channels/1e6).toFixed(1)}} / {{(hydrologyMetrics.storage.lakes/1e6).toFixed(1)}}</strong></div><div><small>CUMULATIVE · hm³ (rain → sea / edge / ET)</small><strong class="date">{{(hydrologyMetrics.cumulative.precipitation/1e6).toFixed(1)}} → {{(hydrologyMetrics.cumulative.ocean_discharge/1e6).toFixed(1)}} / {{(hydrologyMetrics.cumulative.edge_outflow/1e6).toFixed(1)}} / {{(hydrologyMetrics.cumulative.evapotranspiration/1e6).toFixed(1)}}</strong></div><div><small>NETWORK</small><strong class="date">{{hydrologyMetrics.basins}} basins · {{hydrologyMetrics.lakes}} lakes · {{hydrologyMetrics.channel_km}} river cells</strong></div></div><div v-if="oceanMetrics" class="metrics extra-metrics"><div><small>MAIN STREAM</small><strong class="date">{{oceanMetrics.main_stream?oceanMetrics.main_stream.label:'none above threshold'}}</strong></div><div><small>FASTEST CURRENT · STREAMS</small><strong class="date">{{oceanMetrics.max_speed_m_s.toFixed(2)}} m/s · {{oceanMetrics.stream_count}}</strong></div><div><small>OVERTURNING · FORMATION AREA</small><strong class="date">{{oceanMetrics.overturning_sv.toFixed(2)}} Sv · {{oceanMetrics.formation_area_km2.toLocaleString()}} km²</strong></div><div><small>FRESH WATER IN · NET RAIN−EVAPORATION</small><strong class="date">{{(oceanMetrics.river_input_m3_s/1000).toFixed(1)}} ×10³ m³/s ({{oceanMetrics.river_input_sv.toFixed(3)}} Sv) · {{(oceanMetrics.net_precipitation_m3_s/1000).toFixed(1)}} ×10³ m³/s</strong></div><div><small>SALINITY MEAN · MIN SURFACE</small><strong class="date">{{oceanMetrics.mean_salinity_psu.toFixed(2)}} · {{oceanMetrics.min_surface_salinity_psu.toFixed(1)}} psu</strong></div><div><small>PLUMES · FRESHWATER HELD · FRONTS</small><strong class="date">{{oceanMetrics.plume_area_km2.toLocaleString()}} km² · {{oceanMetrics.plume_freshwater_km3.toFixed(0)}} km³ · {{oceanMetrics.front_cells}} cells</strong></div><div><small>CUMULATIVE RIVER · SUNK</small><strong class="date">{{oceanMetrics.cumulative_river_km3.toFixed(0)}} km³ · {{oceanMetrics.cumulative_sinking_km3.toFixed(0)}} km³</strong></div></div><section v-if="oceanSeries.length" class="comparison outlet-report"><div class="section-label">CIRCULATION OVER TIME</div><p>The overturning (deep-water formation), the transport of the strongest stream and the fresh water entering from rivers, over the run.</p><div class="outlet-charts"><div class="comparison-chart"><small>OVERTURNING · Sv</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Overturning time series"><polyline :points="oceanPath('overturning_sv',oceanSeriesMax.overturning)" fill="none" stroke="#b388ff" stroke-width=".7"/><line :x1="oceanTimePosition" :x2="oceanTimePosition" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>0–{{oceanSeriesMax.overturning.toFixed(2)}} Sv · 0–{{(visibleFrames.at(-1).forecast.elapsed_seconds/86400).toFixed(0)}} days</small></div><div class="comparison-chart"><small>MAIN STREAM TRANSPORT · Sv</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Stream transport time series"><polyline :points="oceanPath('stream_sv',oceanSeriesMax.stream)" fill="none" stroke="#75bbfa" stroke-width=".7"/><line :x1="oceanTimePosition" :x2="oceanTimePosition" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>0–{{oceanSeriesMax.stream.toFixed(1)}} Sv</small></div><div class="comparison-chart"><small>RIVER FRESH WATER · Sv</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="River input time series"><polyline :points="oceanPath('river_sv',oceanSeriesMax.river)" fill="none" stroke="#7fffd4" stroke-width=".7"/><line :x1="oceanTimePosition" :x2="oceanTimePosition" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>0–{{oceanSeriesMax.river.toFixed(3)}} Sv</small></div></div><p v-if="data.ocean">Exchange points: <template v-for="(p,i) in data.ocean.exchangePoints" :key="p.name">{{i?' · ':''}}{{p.name}} {{p.discharge_m3_s>=1e5?(p.discharge_m3_s/1e6).toFixed(2)+' Sv':Math.round(p.discharge_m3_s).toLocaleString()+' m³/s'}} → plume {{p.plume_area_km2.toLocaleString()}} km², min {{p.minimum_salinity_psu.toFixed(1)}} psu</template></p></section><div v-if="oceanHeatMetrics" class="metrics extra-metrics"><div><small>SEA SURFACE · MEAN (MIN–MAX)</small><strong class="date">{{oceanHeatMetrics.mean_sst_c.toFixed(2)}} °C ({{oceanHeatMetrics.min_sst_c.toFixed(1)}}–{{oceanHeatMetrics.max_sst_c.toFixed(1)}})</strong></div><div v-if="oceanHeatMetrics.mean_mld_m!==null"><small>MIXED LAYER · MEAN / DEEPEST · BARRIER-LAYER CELLS</small><strong class="date">{{oceanHeatMetrics.mean_mld_m.toFixed(1)}} / {{oceanHeatMetrics.max_mld_m.toFixed(0)}} m · {{oceanHeatMetrics.barrier_layer_cells}}</strong></div><div><small>NET HEAT INTO THE SEA<template v-if="oceanHeatMetrics.fluxes_w_m2"> · SUN / LONGWAVE / SENSIBLE / LATENT</template></small><strong class="date">{{oceanHeatMetrics.net_heat_w_m2.toFixed(0)}} W/m²<template v-if="oceanHeatMetrics.fluxes_w_m2"> · {{oceanHeatMetrics.fluxes_w_m2.shortwave.toFixed(0)}} / {{oceanHeatMetrics.fluxes_w_m2.longwave.toFixed(0)}} / {{oceanHeatMetrics.fluxes_w_m2.sensible.toFixed(0)}} / {{oceanHeatMetrics.fluxes_w_m2.latent.toFixed(0)}}</template></strong></div><div v-if="oceanHeatMetrics.fluxes_w_m2"><small>EVAPORATION · MEAN / MAX</small><strong class="date">{{fmtFlow(oceanHeatMetrics.evaporation_m3_s)}} · {{oceanHeatMetrics.mean_evaporation_mm_day.toFixed(2)}} / {{oceanHeatMetrics.max_evaporation_mm_day.toFixed(1)}} mm/day</strong></div><div v-if="data.ocean.rain"><small>RAIN ON SEA (NEAR COAST) · COAST · INLAND</small><strong class="date">{{fmtFlow(oceanHeatMetrics.rain_sea_m3_s)}} ({{fmtFlow(oceanHeatMetrics.rain_coastal_sea_m3_s)}}) · {{fmtFlow(oceanHeatMetrics.rain_coast_m3_s)}} · {{fmtFlow(oceanHeatMetrics.rain_inland_m3_s)}}</strong></div><div v-if="data.ocean.rain"><small>COASTAL RUNOFF → SEA · STILL ON LAND · PEAK RAIN</small><strong class="date">{{fmtFlow(oceanHeatMetrics.coastal_runoff_m3_s)}} · {{(oceanHeatMetrics.coastal_storage_m3/1e9).toFixed(2)}} km³ · {{oceanHeatMetrics.max_rain_mm_h.toFixed(1)}} mm/h</strong></div><div><small>RAIN − EVAPORATION OVER THE SEA</small><strong>{{oceanHeatMetrics.precipitation_minus_evaporation_mm_day.toFixed(2)}} <em>mm/day</em></strong></div><div><small>SURFACE LENSES (RAIN) · LARGEST</small><strong class="date">{{oceanHeatMetrics.lens_count}} ({{oceanHeatMetrics.rain_lens_count}}) · {{oceanHeatMetrics.largest_lens?`${oceanHeatMetrics.largest_lens.kind.replace('_',' ')} ${Math.round(oceanHeatMetrics.largest_lens.area_km2).toLocaleString()} km², ${oceanHeatMetrics.largest_lens.min_salinity_psu.toFixed(1)} psu`:'none'}}</strong></div><div><small>HEAT GAINED SINCE START · BUDGET RESIDUAL</small><strong class="date">{{oceanHeatMetrics.heat_change_ej.toFixed(1)}} EJ · {{oceanHeatMetrics.heat_balance_error_j.toExponential(1)}} J</strong></div><div><small>CUMULATIVE RAIN SEA / COAST · RUNOFF · EVAPORATION</small><strong class="date">{{oceanHeatMetrics.cumulative.rain_sea_km3.toFixed(1)}} / {{oceanHeatMetrics.cumulative.rain_coast_km3.toFixed(1)}} · {{oceanHeatMetrics.cumulative.runoff_km3.toFixed(1)}} · {{oceanHeatMetrics.cumulative.evaporation_km3.toFixed(1)}} km³</strong></div></div><section v-if="oceanHeatSeries.length" class="comparison outlet-report"><div class="section-label">OCEAN HEAT &amp; WATER EXCHANGE OVER TIME</div><p>Basin means over the run: the sea surface and its mixed layer, the net heat the air and the sun give the sea (above the line the sea warms), and the fresh water it exchanges with the air and the land.</p><div class="outlet-charts"><div class="comparison-chart"><small>SEA SURFACE °C (orange) · MIXED LAYER m (blue)</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Sea-surface temperature and mixed-layer depth time series"><polyline :points="heatPath('sst_c',v=>45-(v-oceanHeatMax.sst[0])/((oceanHeatMax.sst[1]-oceanHeatMax.sst[0])||1)*40)" fill="none" stroke="#ffb366" stroke-width=".7"/><polyline :points="heatPath('mld_m',v=>45-v/oceanHeatMax.mld*40)" fill="none" stroke="#75bbfa" stroke-width=".7"/><line :x1="oceanTimePosition" :x2="oceanTimePosition" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>{{oceanHeatMax.sst[0].toFixed(2)}}–{{oceanHeatMax.sst[1].toFixed(2)}} °C · 0–{{oceanHeatMax.mld.toFixed(0)}} m</small></div><div class="comparison-chart"><small>NET HEAT INTO THE SEA · W/m²</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Net air-sea heat flux time series"><line x1="0" x2="100" y1="25" y2="25" stroke="#4a5a66" stroke-width=".3"/><polyline :points="heatPath('net_heat_w_m2',v=>25-v/oceanHeatMax.net*22)" fill="none" stroke="#ff7b6b" stroke-width=".7"/><line :x1="oceanTimePosition" :x2="oceanTimePosition" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>±{{oceanHeatMax.net.toFixed(0)}} W/m² (day and night, outbreaks)</small></div><div class="comparison-chart"><small>FRESH WATER · rain on sea (blue) · coastal runoff (tan) · evaporation (orange)</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Freshwater exchange time series"><polyline :points="heatPath('rain_sea_m3_s',v=>45-v/oceanHeatMax.water*40)" fill="none" stroke="#75bbfa" stroke-width=".7"/><polyline :points="heatPath('runoff_m3_s',v=>45-v/oceanHeatMax.water*40)" fill="none" stroke="#d8b77a" stroke-width=".7"/><polyline :points="heatPath('evaporation_m3_s',v=>45-v/oceanHeatMax.water*40)" fill="none" stroke="#ffb366" stroke-width=".7"/><line :x1="oceanTimePosition" :x2="oceanTimePosition" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>0–{{fmtFlow(oceanHeatMax.water)}}</small></div></div></section><div v-if="oceanPolarMetrics" class="metrics extra-metrics"><div><small>OVERTURNING NOW · ANNUAL MEAN OF YEAR 1 → LATEST</small><strong class="date">{{oceanPolarMetrics.overturning_sv.toFixed(1)}} Sv<template v-if="oceanPolarEvents"> · {{oceanPolarEvents.reference_sv.toFixed(1)}} → {{oceanPolarYears.at(-1).overturning_mean_sv.toFixed(1)}} Sv ({{oceanPolarEvents.last_pct.toFixed(0)}} %)</template></strong></div><div><small>EXTRA FRESH WATER · HOSING / ALL GLACIAL (HOSING + MELT + ICEBERGS)</small><strong class="date">{{oceanPolarMetrics.hosing_sv.toFixed(3)}} / {{oceanPolarMetrics.glacial_sv.toFixed(3)}} Sv · {{oceanPolarMetrics.cumulative_glacial_km3.toFixed(0)}} km³ so far</strong></div><div v-if="oceanWarming"><small>AIR WARMING · SOUTH / NORTH</small><strong class="date">+{{oceanWarming.south.toFixed(2)}} / +{{oceanWarming.north.toFixed(2)}} K</strong></div><div v-if="oceanPolarMetrics.sea_ice_area_mkm2!==null"><small>SEA ICE · AREA / EXTENT / VOLUME</small><strong class="date">{{oceanPolarMetrics.sea_ice_area_mkm2.toFixed(2)}} / {{oceanPolarMetrics.sea_ice_extent_mkm2.toFixed(2)}} M km² · {{oceanPolarMetrics.sea_ice_volume_km3.toFixed(0)}} km³ · {{oceanPolarMetrics.sea_ice_water_m3_s>=0?'melting':'freezing'}} {{fmtFlow(Math.abs(oceanPolarMetrics.sea_ice_water_m3_s))}} · drift up to {{(oceanPolarMetrics.sea_ice_max_drift_m_s*86.4).toFixed(0)}} km/day</strong></div><div v-if="oceanPolarMetrics.greenland_smb_gt_yr!==null"><small>ICE SHEET · SMB / DISCHARGE / SEA LEVEL</small><strong class="date">{{oceanPolarMetrics.greenland_smb_gt_yr.toFixed(0)}} Gt/yr · {{fmtFlow(oceanPolarMetrics.greenland_discharge_m3_s)}} · +{{oceanPolarMetrics.greenland_sea_level_rise_mm.toFixed(2)}} mm</strong></div><div><small>NORTH · SEA SURFACE / MIXED LAYER / O₂ CAPACITY</small><strong class="date">{{oceanPolarMetrics.north_sst_c.toFixed(2)}} °C · {{oceanPolarMetrics.north_mld_m===null?'–':oceanPolarMetrics.north_mld_m.toFixed(0)+' m'}} · {{oceanPolarMetrics.north_oxygen_umol_kg===null?'–':oceanPolarMetrics.north_oxygen_umol_kg.toFixed(0)+' µmol/kg'}}</strong></div></div><section v-if="oceanPolarSeries.length>1" class="comparison outlet-report"><div class="section-label">POLAR OCEAN OVER TIME · SEA ICE, MELTWATER AND THE OVERTURNING</div><p>The deep-water formation has a strong seasonal cycle (winter convection), so the dots mark each model year's mean. The fresh water from the ice sheet and the hosing caps the sinking region with light water; warming thins the winter sea ice and shrinks the area where the water gets cold and dense enough to sink.</p><div class="outlet-charts"><div v-if="poChartOverturning" class="comparison-chart"><small>OVERTURNING · Sv (dots: annual means)</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Overturning time series"><line x1="0" x2="100" :y1="poChartOverturning.zero" :y2="poChartOverturning.zero" stroke="#4a5a66" stroke-width=".3"/><polyline v-for="l in poChartOverturning.lines" :key="l.key" :points="l.points" fill="none" :stroke="l.color" stroke-width=".7"/><line :x1="poChartOverturning.x" :x2="poChartOverturning.x" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/><circle v-for="(y,k) in poChartOverturning.years" :key="k" :cx="y.x" :cy="y.y" r=".9" fill="#e0c8ff"/></svg><small>{{poChartOverturning.lo.toFixed(0)}}–{{poChartOverturning.hi.toFixed(0)}} Sv</small></div><div v-if="poChartFresh" class="comparison-chart"><small>EXTRA FRESH WATER · all glacial incl. hosing (teal) · hosing alone (yellow) · Sv</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Glacial and hosing freshwater time series"><line x1="0" x2="100" :y1="poChartFresh.zero" :y2="poChartFresh.zero" stroke="#4a5a66" stroke-width=".3"/><polyline v-for="l in poChartFresh.lines" :key="l.key" :points="l.points" fill="none" :stroke="l.color" stroke-width=".7"/><line :x1="poChartFresh.x" :x2="poChartFresh.x" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>0–{{poChartFresh.hi.toFixed(2)}} Sv</small></div><div v-if="poChartSeaIce" class="comparison-chart"><small>SEA-ICE AREA · million km²</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Sea-ice area time series"><line x1="0" x2="100" :y1="poChartSeaIce.zero" :y2="poChartSeaIce.zero" stroke="#4a5a66" stroke-width=".3"/><polyline v-for="l in poChartSeaIce.lines" :key="l.key" :points="l.points" fill="none" :stroke="l.color" stroke-width=".7"/><line :x1="poChartSeaIce.x" :x2="poChartSeaIce.x" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>0–{{poChartSeaIce.hi.toFixed(2)}} M km²</small></div><div v-if="poChartGreenland" class="comparison-chart"><small>ICE-SHEET SURFACE MASS BALANCE · Gt/yr</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Ice-sheet surface mass balance time series"><line x1="0" x2="100" :y1="poChartGreenland.zero" :y2="poChartGreenland.zero" stroke="#4a5a66" stroke-width=".3"/><polyline v-for="l in poChartGreenland.lines" :key="l.key" :points="l.points" fill="none" :stroke="l.color" stroke-width=".7"/><line :x1="poChartGreenland.x" :x2="poChartGreenland.x" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>{{poChartGreenland.lo.toFixed(0)}}–{{poChartGreenland.hi.toFixed(0)}} Gt/yr (below the line it loses mass)</small></div><div v-if="poChartNorth" class="comparison-chart"><small>NORTHERN SEA SURFACE · °C</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Northern sea-surface temperature time series"><line x1="0" x2="100" :y1="poChartNorth.zero" :y2="poChartNorth.zero" stroke="#4a5a66" stroke-width=".3"/><polyline v-for="l in poChartNorth.lines" :key="l.key" :points="l.points" fill="none" :stroke="l.color" stroke-width=".7"/><line :x1="poChartNorth.x" :x2="poChartNorth.x" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>{{poChartNorth.lo.toFixed(1)}}–{{poChartNorth.hi.toFixed(1)}} °C</small></div><div v-if="poChartOxygen" class="comparison-chart"><small>NORTHERN O₂ CAPACITY · µmol/kg</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Northern surface oxygen time series"><line x1="0" x2="100" :y1="poChartOxygen.zero" :y2="poChartOxygen.zero" stroke="#4a5a66" stroke-width=".3"/><polyline v-for="l in poChartOxygen.lines" :key="l.key" :points="l.points" fill="none" :stroke="l.color" stroke-width=".7"/><line :x1="poChartOxygen.x" :x2="poChartOxygen.x" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>{{poChartOxygen.lo.toFixed(0)}}–{{poChartOxygen.hi.toFixed(0)}} µmol/kg (warmer water holds less)</small></div></div></section><section v-if="oceanPolarEvents" class="comparison outlet-report"><div class="section-label">WHEN DOES THE OVERTURNING WEAKEN? · YEAR BY YEAR</div><p>Annual means of each complete model year (year 0 is the first year after the spin-up). Weakened / collapsed: the first year whose mean overturning falls below 75 %, 50 % or 20 % of year 0. <strong>25 %: {{oceanPolarEvents.weakened_25pct===null?'not yet':'year '+oceanPolarEvents.weakened_25pct}} · 50 %: {{oceanPolarEvents.weakened_50pct===null?'not yet':'year '+oceanPolarEvents.weakened_50pct}} · collapse: {{oceanPolarEvents.collapsed===null?'not within the run':'year '+oceanPolarEvents.collapsed}} · first ice-free summer: {{oceanPolarEvents.ice_free_summer===null?'none':'year '+oceanPolarEvents.ice_free_summer}}{{oceanPolarEvents.greenland_negative_smb===null?'':' · ice sheet loses mass at the surface from year '+oceanPolarEvents.greenland_negative_smb}}</strong></p><table class="event-table"><thead><tr><th>Year</th><th>Overturning mean / winter max (Sv)</th><th>Glacial water incl. hosing (Sv)</th><th>Sea ice max / min (M km²)</th><th>North SST (°C)</th><th>North O₂ (µmol/kg)</th><th>Deepest north mixing (m)</th><th>Ice-sheet SMB (Gt/yr)</th><th>Sea level (mm)</th></tr></thead><tbody><tr v-for="y in oceanPolarYears" :key="y.year" :class="{selected:y.year===Math.floor(forecast.elapsed_seconds/31557600+1e-9)}" @click="seekYear(y.year)"><td>{{y.year}}</td><td>{{y.overturning_mean_sv.toFixed(1)}} / {{y.overturning_max_sv.toFixed(1)}}</td><td>{{y.glacial_sv.toFixed(3)}}</td><td>{{y.sea_ice_max_mkm2===null?'–':y.sea_ice_max_mkm2.toFixed(2)+' / '+y.sea_ice_min_mkm2.toFixed(2)}}</td><td>{{y.north_sst_c.toFixed(2)}}</td><td>{{y.north_oxygen_umol_kg===null?'–':y.north_oxygen_umol_kg.toFixed(0)}}</td><td>{{y.north_mld_max_m===null?'–':y.north_mld_max_m.toFixed(0)}}</td><td>{{y.greenland_smb_gt_yr===null?'–':y.greenland_smb_gt_yr.toFixed(0)}}</td><td>{{y.greenland_sea_level_rise_mm===null?'–':y.greenland_sea_level_rise_mm.toFixed(2)}}</td></tr></tbody></table><p v-if="oceanSameSeason.length>1">Same time of year as the current frame ({{time.slice(5,10)}}), year by year: <span v-for="r in oceanSameSeason" :key="r.k" :class="{'selected-year':r.k===frameIndex}" style="margin-right:.9em">year {{r.year.toFixed(0)}}: {{r.overturning_sv.toFixed(1)}} Sv{{r.sea_ice_area_mkm2===null?'':' · ice '+r.sea_ice_area_mkm2.toFixed(2)+' M km²'}}</span></p></section><section v-if="columnNow" class="comparison outlet-report"><div class="section-label">WATER COLUMN · {{chosen&&data.ocean.mask[chosen.i]?`SELECTED CELL ${columnCell}`:`STRONGEST COOLING OVER THE RUN (CELL ${columnCell})`}}</div><p>Temperature (red) and salinity (green) of the {{columnNow.layers.length}} layers from the surface down to the thermocline ({{columnNow.thickness_m.toFixed(0)}} m) at the current time; dashed: mixed-layer depth, dotted: isothermal-layer depth (a gap between them is a barrier layer). The section shows the same column over the whole run with the mixed layer in white. Depth on a square-root scale. Click a sea cell to move the column.</p><div class="outlet-charts"><div class="comparison-chart"><small>PROFILE · {{(columnTemperatureRange[0]-273.15).toFixed(1)}}–{{(columnTemperatureRange[1]-273.15).toFixed(1)}} °C · {{columnSalinityRange[0].toFixed(2)}}–{{columnSalinityRange[1].toFixed(2)}} psu</small><svg viewBox="0 0 100 60" preserveAspectRatio="none" aria-label="Temperature and salinity profile"><polyline :points="columnStep('temperature_k',columnTemperatureRange)" fill="none" stroke="#ff7b6b" stroke-width=".8"/><polyline :points="columnStep('salinity_psu',columnSalinityRange)" fill="none" stroke="#7fe08a" stroke-width=".8"/><line x1="0" x2="100" :y1="columnDepthY(columnNow.mixed_layer_depth_m,columnNow.thickness_m)" :y2="columnDepthY(columnNow.mixed_layer_depth_m,columnNow.thickness_m)" stroke="#f3f7f9" stroke-dasharray="2 1" stroke-width=".4"/><line x1="0" x2="100" :y1="columnDepthY(columnNow.isothermal_layer_depth_m,columnNow.thickness_m)" :y2="columnDepthY(columnNow.isothermal_layer_depth_m,columnNow.thickness_m)" stroke="#ffd166" stroke-dasharray=".5 1" stroke-width=".4"/></svg><small>surface {{(columnNow.sst_k-273.15).toFixed(2)}} °C · mixed layer {{columnNow.mixed_layer_depth_m.toFixed(1)}} m · isothermal {{columnNow.isothermal_layer_depth_m.toFixed(1)}} m{{columnNow.barrier_layer_m>1?` · barrier ${columnNow.barrier_layer_m.toFixed(1)} m`:''}}</small></div><div v-if="columnHistory" class="comparison-chart"><small>TEMPERATURE SECTION · {{(columnHistory.temperature_range_k[0]-273.15).toFixed(1)}}–{{(columnHistory.temperature_range_k[1]-273.15).toFixed(1)}} °C (blue → red)</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Time-depth temperature section"><rect v-for="(r,k) in sectionRects" :key="k" :x="r.x" :y="r.y" :width="r.w+.02" :height="r.h+.02" :fill="r.fill"/><polyline :points="sectionMld" fill="none" stroke="#f3f7f9" stroke-width=".5"/><line :x1="sectionTimePosition" :x2="sectionTimePosition" y1="0" y2="50" stroke="#ffd166" stroke-dasharray="1 1" stroke-width=".4"/></svg><small>{{((columnHistory.end-columnHistory.start)/86400).toFixed(1)}} days · √depth 0–{{columnHistory.max_depth_m.toFixed(0)}} m</small></div></div></section><template v-if="polarMetrics"><div class="metrics extra-metrics"><div><small>SCENARIO · YEAR · GLOBAL WARMING</small><strong class="date">{{polarMetrics.scenario}} · {{polarMetrics.year}} · +{{fmt(polarMetrics.global_warming_k,2)}} K</strong></div><div><small>ATLANTIC OVERTURNING (AMOC)</small><strong class="date">{{fmt(polarMetrics.overturning_sv,1)}} Sv · {{fmt(polarMetrics.overturning_pct,0)}} % of today · heat {{fmt(polarMetrics.heat_transport_pw,2)}} PW</strong></div><div><small>FRESH WATER INTO THE NORTH ATLANTIC · TIPPING POINT</small><strong class="date">{{fmt(polarMetrics.freshwater_sv,3)}} / {{fmt(polarMetrics.threshold_sv,3)}} Sv{{polarMetrics.freshwater_sv>polarMetrics.threshold_sv?' · past the tipping point':''}}</strong></div><div><small>EXTRA FRESH WATER · GREENLAND / ARCTIC / RAIN &amp; RIVERS</small><strong class="date">{{fmt(polarMetrics.freshwater_components_sv.greenland,3)}} / {{fmt(polarMetrics.freshwater_components_sv.arctic,3)}} / {{fmt(polarMetrics.freshwater_components_sv.hydrological,3)}} Sv</strong></div><div><small>RECOVERY TIME (CRITICAL SLOWING DOWN)</small><strong class="date">{{polarMetrics.recovery_time_years===null?'no stable state left':fmt(polarMetrics.recovery_time_years,0)+' years'}}</strong></div><div><small>GREENLAND · SEA LEVEL (VS CONTROL) · SMB</small><strong class="date">{{fmt(polarMetrics.greenland_sle_m,2)}} m left · +{{fmt((polarMetrics.sea_level_rise_vs_control_m??polarMetrics.sea_level_rise_m)*100,1)}} cm · {{fmt(polarMetrics.greenland_smb_gt_yr,0)}} Gt/yr</strong></div><div><small>ARCTIC SEA ICE · MARCH / SEPTEMBER · ICE-FREE DAYS</small><strong class="date">{{fmt(polarMetrics.arctic_ice_march_m,2)}} / {{fmt(polarMetrics.arctic_ice_september_m,2)}} m · {{fmt(polarMetrics.arctic_ice_free_days,0)}}</strong></div><div><small>OCEAN TEMPERATURE CHANGE · NORTH ATLANTIC / TROPICS</small><strong class="date">{{fmt(polarMetrics.north_atlantic_change_k,2)}} / {{fmt(polarMetrics.tropical_atlantic_change_k,2)}} K</strong></div><div><small>DISSOLVED-OXYGEN CAPACITY · NORTH / TROPICS</small><strong class="date">{{fmt(polarMetrics.north_oxygen_change_pct,1)}} / {{fmt(polarMetrics.south_oxygen_change_pct,1)}} %</strong></div></div>
<section class="comparison outlet-report"><div class="section-label">WHEN DO THE CURRENTS COLLAPSE?</div><p>Per scenario: the year (and global warming) of each event in the central run, and across the uncertainty ensemble (present salinity contrast = distance to the tipping point × Greenland warming sensitivity). The tipping point is crossed when the fresh water into the North Atlantic exceeds what the weakened circulation can carry; the collapse follows later because the circulation lingers near the vanished state. Conceptual overturning model: read the dates relative to each other and to the scenarios, not as a forecast.</p><table class="comparison-table"><thead><tr><th>Scenario</th><th>Ice-free Sept.</th><th>Greenland SMB &lt; 0</th><th>Tipping point</th><th>−50 %</th><th>Collapse</th><th>Ensemble: tipped / collapsed (range)</th><th>Sea level 2100 · end</th></tr></thead><tbody><tr v-for="r in polarEvents" :key="r.scenario" :class="{selected:r.scenario===polarScenario}" @click="polarLayers.scenario=r.scenario"><td>{{r.scenario}}</td><td>{{eventCell(r.events.first_ice_free_september)}}</td><td>{{eventCell(r.events.greenland_negative_smb)}}</td><td>{{eventCell(r.events.threshold_crossed)}}</td><td>{{eventCell(r.events.overturning_weakened_50pct)}}</td><td><strong>{{eventCell(r.events.overturning_collapsed)}}</strong>{{r.lag_years!==null?` · ${r.lag_years} yr after tipping`:''}}</td><td>{{r.ensemble?`${r.ensemble.crossed}/${r.ensemble.members} · ${r.ensemble.collapsed}/${r.ensemble.members}${r.ensemble.collapsed?` (${r.ensemble.earliest}–${r.ensemble.latest})`:''}`:'—'}}</td><td>+{{fmt(r.sea_level_2100_m*100,0)}} · +{{fmt(r.sea_level_end_m*100,0)}} cm</td></tr></tbody></table><p v-for="r in polarEvents.filter(r=>r.early_warning)" :key="'ews'+r.scenario">Early warnings in the noisy {{r.scenario}} record ({{r.early_warning.window}}-year windows until {{r.early_warning.until}}): trend of the variance τ = {{r.early_warning.variance_tau.toFixed(2)}}, of the lag-1 autocorrelation τ = {{r.early_warning.autocorrelation_tau.toFixed(2)}} (Kendall; near 1 = rising steadily, near 0 = no trend).</p></section>
<section class="comparison outlet-report"><div class="section-label">SCENARIOS OVER TIME · {{polarBlock.output_years[0]}}–{{polarBlock.output_years.at(-1)}}</div><p><span v-for="(s,k) in polarBlock.scenarios" :key="s.name" :style="{color:scenarioColor(k-(polarBlock.scenarios[0].control?1:0),s.control),marginRight:'1em'}">■ {{s.name}}</span> · the dotted grey line is the control (model drift); the dashed vertical line is the current frame.</p><div class="outlet-charts"><div class="comparison-chart"><small>ATLANTIC OVERTURNING · Sv</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Overturning by scenario"><line x1="0" x2="100" :y1="chartOverturning.zero" :y2="chartOverturning.zero" stroke="#4a5a66" stroke-width=".3"/><polyline v-for="l in chartOverturning.lines" :key="l.name" :points="l.points" fill="none" :stroke="l.color" :stroke-width="l.width" :stroke-dasharray="l.control?'1 1':null"/><line :x1="chartOverturning.x" :x2="chartOverturning.x" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>{{chartOverturning.lo.toFixed(1)}}–{{chartOverturning.hi.toFixed(1)}} Sv</small></div><div class="comparison-chart"><small>SEA LEVEL FROM GREENLAND (VS CONTROL) · cm</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Sea-level rise by scenario"><line x1="0" x2="100" :y1="chartSeaLevel.zero" :y2="chartSeaLevel.zero" stroke="#4a5a66" stroke-width=".3"/><polyline v-for="l in chartSeaLevel.lines" :key="l.name" :points="l.points" fill="none" :stroke="l.color" :stroke-width="l.width" :stroke-dasharray="l.control?'1 1':null"/><line :x1="chartSeaLevel.x" :x2="chartSeaLevel.x" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>{{chartSeaLevel.lo.toFixed(1)}}–{{chartSeaLevel.hi.toFixed(1)}} cm</small></div><div class="comparison-chart"><small>ARCTIC SEPTEMBER ICE · m (thickness × cover)</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="September sea ice by scenario"><line x1="0" x2="100" :y1="chartSeptemberIce.zero" :y2="chartSeptemberIce.zero" stroke="#4a5a66" stroke-width=".3"/><polyline v-for="l in chartSeptemberIce.lines" :key="l.name" :points="l.points" fill="none" :stroke="l.color" :stroke-width="l.width" :stroke-dasharray="l.control?'1 1':null"/><line :x1="chartSeptemberIce.x" :x2="chartSeptemberIce.x" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>{{chartSeptemberIce.lo.toFixed(2)}}–{{chartSeptemberIce.hi.toFixed(2)}} m</small></div><div class="comparison-chart"><small>NORTH ATLANTIC TEMPERATURE CHANGE · K</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="North Atlantic temperature change by scenario"><line x1="0" x2="100" :y1="chartNorthAtlantic.zero" :y2="chartNorthAtlantic.zero" stroke="#4a5a66" stroke-width=".3"/><polyline v-for="l in chartNorthAtlantic.lines" :key="l.name" :points="l.points" fill="none" :stroke="l.color" :stroke-width="l.width" :stroke-dasharray="l.control?'1 1':null"/><line :x1="chartNorthAtlantic.x" :x2="chartNorthAtlantic.x" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>{{chartNorthAtlantic.lo.toFixed(1)}}–{{chartNorthAtlantic.hi.toFixed(1)}} K</small></div><div class="comparison-chart"><small>NORTH ATLANTIC OXYGEN CAPACITY · %</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Oxygen solubility change by scenario"><line x1="0" x2="100" :y1="chartOxygen.zero" :y2="chartOxygen.zero" stroke="#4a5a66" stroke-width=".3"/><polyline v-for="l in chartOxygen.lines" :key="l.name" :points="l.points" fill="none" :stroke="l.color" :stroke-width="l.width" :stroke-dasharray="l.control?'1 1':null"/><line :x1="chartOxygen.x" :x2="chartOxygen.x" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>{{chartOxygen.lo.toFixed(1)}}–{{chartOxygen.hi.toFixed(1)}} %</small></div><div v-if="chartThreshold" class="comparison-chart"><small>FRESH WATER (BLUE) VS TIPPING POINT (RED) · {{polarScenario}}</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Freshwater forcing against the tipping point"><polyline :points="chartThreshold.threshold" fill="none" stroke="#ff6b6b" stroke-width=".7"/><polyline :points="chartThreshold.forcing" fill="none" stroke="#75bbfa" stroke-width=".7"/><line :x1="chartThreshold.x" :x2="chartThreshold.x" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>{{chartThreshold.lo.toFixed(3)}}–{{chartThreshold.hi.toFixed(3)}} Sv · the circulation tips where blue crosses red</small></div></div></section>
<section v-if="equilibrium" class="comparison outlet-report"><div class="section-label">EQUILIBRIUM DIAGRAM OF THE OVERTURNING</div><p>Steady states against the fresh water into the North Atlantic: strong sinking-north circulation (solid, stable), the unstable middle branch (dashed) and the reversed salinity-driven state (lower, stable), for the start climate (bright) and at +{{equilibrium.warmest.warming.toFixed(1)}} K (faded: warming shifts the tipping point left). The coloured path is the “{{polarScenario}}” run; the dot is the current frame; the grey line today's forcing. Once the path runs past the end of the strong branch there is no way back short of net evaporation.</p><svg class="equilibrium" viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Overturning equilibrium diagram"><line x1="0" x2="100" :y1="equilibrium.zero" :y2="equilibrium.zero" stroke="#4a5a66" stroke-width=".3"/><line :x1="equilibrium.present" :x2="equilibrium.present" y1="0" y2="50" stroke="#93a5af" stroke-width=".3"/><polyline :points="equilibrium.warmest.strong" fill="none" stroke="#7fd1ff" stroke-opacity=".35" stroke-width=".6"/><polyline :points="equilibrium.warmest.unstable" fill="none" stroke="#7fd1ff" stroke-opacity=".35" stroke-dasharray="1 1" stroke-width=".5"/><polyline :points="equilibrium.warmest.reversed" fill="none" stroke="#b388ff" stroke-opacity=".35" stroke-width=".6"/><polyline :points="equilibrium.start.strong" fill="none" stroke="#7fd1ff" stroke-width=".8"/><polyline :points="equilibrium.start.unstable" fill="none" stroke="#7fd1ff" stroke-dasharray="1 1" stroke-width=".6"/><polyline :points="equilibrium.start.reversed" fill="none" stroke="#b388ff" stroke-width=".8"/><polyline :points="equilibrium.trajectory" fill="none" stroke="#ffd166" stroke-width=".6"/><circle :cx="equilibrium.now.x" :cy="equilibrium.now.y" r="1.1" fill="#ffd166"/></svg><small>fresh water 0–{{equilibrium.fmax.toFixed(2)}} Sv (right) · overturning {{equilibrium.qlo.toFixed(0)}}–{{equilibrium.qhi.toFixed(0)}} Sv (up)</small></section></template><template v-if="coastSummary"><div class="metrics extra-metrics"><div title="Regional rise at this coast (the global mean with the fingerprints of the ice sources) and the global mean, counted from today."><small>SEA LEVEL · HERE / GLOBAL · {{coastSummary.year}} · {{coastSummary.warming_k.toFixed(1)}} K WARMER</small><strong class="date">+{{coastSummary.regional_rise_m.toFixed(2)}} m / +{{coastSummary.global_rise_m.toFixed(2)}} m</strong></div><div title="Land permanently under the daily high water (compared with today) plus land eroded from sandy shores."><small>LAND LOST · PEOPLE WHO LIVED ON IT</small><strong class="date">{{coastSummary.lost_km2.toFixed(0)}} km² · {{fmtPeople(coastSummary.people_on_lost_land)}}</strong></div><div title="People whose homes the 100-year storm floods: today and in this year."><small>PEOPLE UNDER THE 100-YEAR STORM · TODAY → NOW</small><strong class="date">{{fmtPeople(coastSummary.people_storm_today)}} → {{fmtPeople(coastSummary.people_storm_flooded)}}</strong></div><div title="Land below the daily high water that only dikes and walls keep dry: its future depends on the defences."><small>BELOW HIGH WATER, BEHIND DEFENCES</small><strong class="date">{{coastSummary.protected_low_km2.toFixed(0)}} km² · {{fmtPeople(coastSummary.people_protected_low)}} people</strong></div><div title="Return period of the flood that comes once a century today, per region (lowest to highest)."><small>TODAY'S 100-YEAR FLOOD NOW COMES</small><strong class="date">{{fmtYears(Math.min(...coastSummary.regions.map(r=>r.design_flood_return_years)))}} – {{fmtYears(Math.max(...coastSummary.regions.map(r=>r.design_flood_return_years)))}}</strong></div><div title="Water piled up by the design storm's onshore wind: the most anywhere and the mean along the coast."><small>WIND SETUP · MAX / COAST MEAN</small><strong class="date">{{coastSummary.max_setup_m.toFixed(2)}} / {{coastSummary.mean_setup_m.toFixed(2)}} m</strong></div></div>
<section class="comparison outlet-report"><div class="section-label">WHAT RAISES THE SEA · {{coastSummary.scenario}} · {{coastSummary.year}}</div><p>The rise still to come since {{data.coast.block.reference_year}}, by source (global mean). Greenland comes from the polar-melt run; here, far from Greenland, a fingerprint weights each ice source (Greenland ×{{data.coast.block.sea_level_source.fingerprints.greenland}}, Antarctica ×{{data.coast.block.sea_level_source.fingerprints.antarctic}}, glaciers ×{{data.coast.block.sea_level_source.fingerprints.glaciers}}), and sinking land adds its own rise on top.</p><svg class="component-bar" viewBox="0 0 100 8" preserveAspectRatio="none" aria-label="Sea-level rise by source"><rect v-for="c in coastComponentBar" :key="c.key" :x="c.x" y="0" :width="c.w" height="8" :fill="c.color"><title>{{c.label}}: {{c.value.toFixed(3)}} m</title></rect></svg><p><span v-for="c in coastComponentBar" :key="c.key" :style="{color:c.color,marginRight:'1.2em'}">■ {{c.label}} {{(c.value*100).toFixed(0)}} cm</span></p></section>
<section class="comparison outlet-report"><div class="section-label">WHERE DOES IT HIT HARDEST? · {{coastSummary.year}}</div><p>The regions of the coast ranked by <select v-model="coastLayers.rank" aria-label="Ranking metric"><option v-for="(m,k) in RANK_METRICS" :key="k" :value="k">{{m.label}}</option></select> under “{{coastSummary.scenario}}”. Click a row to fly there on the map.</p><table class="event-table"><thead><tr><th>#</th><th>Region</th><th title="Share of the region's land lost to the sea">Land lost</th><th title="People who lived on the land now lost">People displaced</th><th title="People whose homes the 100-year storm floods (today → now)">Under the 100-yr storm</th><th title="Land below high water kept dry only by defences">Behind defences</th><th title="How often today's 100-year flood comes now">100-yr flood now</th><th title="Mean relative rise at the region's coast, including land subsidence">Relative rise</th></tr></thead><tbody><tr v-for="r in coastRank" :key="r.name" :class="{selected:coastFocus===r.index}" @click="focusRegion(r.index)"><td>{{r.rank}}</td><td>{{r.name}}</td><td><strong v-if="r.lost_pct>=10">{{r.lost_pct.toFixed(1)}} %</strong><template v-else>{{r.lost_pct.toFixed(1)}} %</template></td><td>{{fmtPeople(r.people_on_lost_land)}}</td><td>{{fmtPeople(r.people_storm_today)}} → {{fmtPeople(r.people_storm_flooded)}}</td><td>{{r.protected_low_km2.toFixed(0)}} km² · {{fmtPeople(r.people_protected_low)}}</td><td>{{fmtYears(r.design_flood_return_years)}}</td><td>+{{r.relative_rise_m.toFixed(2)}} m</td></tr></tbody></table></section>
<section class="comparison outlet-report"><div class="section-label">WHEN? · EVENTS PER REGION AND SCENARIO</div><p>The first year each threshold is passed (— = not by {{data.coast.block.output_years.at(-1)}}). Defences are overtopped when the 100-year storm reaches land that lies below high water behind them.</p><table class="event-table"><thead><tr><th>Region</th><th>Scenario</th><th v-for="e in COAST_EVENTS" :key="e" :title="COAST_EVENT_LABELS[e]">{{COAST_EVENT_LABELS[e]}}</th></tr></thead><tbody><template v-for="r in coastEvents" :key="r.region"><tr v-for="(x,k) in r.scenarios" :key="r.region+x.name" :class="{selected:x.name===coastScenario}"><td>{{k===0?r.region:''}}</td><td :style="{color:scenarioTint(k)}">{{x.name}}</td><td v-for="e in COAST_EVENTS" :key="e">{{x.events[e]??'—'}}</td></tr></template></tbody></table></section>
<section class="comparison outlet-report"><div class="section-label">OVER TIME · {{data.coast.block.output_years[0]}}–{{data.coast.block.output_years.at(-1)}}</div><p><span v-for="(x,k) in data.coast.block.scenarios" :key="x.name" :style="{color:scenarioTint(k),marginRight:'1em'}">■ {{x.name}}</span> · bold: the scenario in focus; dashed in the sea-level chart: its global mean.</p><div class="outlet-charts"><div v-if="coastChartSea" class="comparison-chart"><small>SEA LEVEL HERE · m above today</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Regional sea-level rise per scenario"><line x1="0" x2="100" :y1="coastChartSea.zero" :y2="coastChartSea.zero" stroke="#4a5a66" stroke-width=".3"/><polyline v-for="l in coastChartSea.lines" :key="l.name" :points="l.points" fill="none" :stroke="l.color" :stroke-width="l.width" :stroke-dasharray="l.dash"/><line :x1="coastChartSea.x" :x2="coastChartSea.x" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>{{coastChartSea.lo.toFixed(1)}}–{{coastChartSea.hi.toFixed(1)}} m</small></div><div v-if="coastChartLost" class="comparison-chart"><small>LAND LOST · km²</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Land lost per scenario"><line x1="0" x2="100" :y1="coastChartLost.zero" :y2="coastChartLost.zero" stroke="#4a5a66" stroke-width=".3"/><polyline v-for="l in coastChartLost.lines" :key="l.name" :points="l.points" fill="none" :stroke="l.color" :stroke-width="l.width" :stroke-dasharray="l.dash"/><line :x1="coastChartLost.x" :x2="coastChartLost.x" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>0–{{coastChartLost.hi.toFixed(0)}} km²</small></div><div v-if="coastChartPeople" class="comparison-chart"><small>PEOPLE UNDER THE 100-YEAR STORM · millions</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="People flooded by the design storm per scenario"><line x1="0" x2="100" :y1="coastChartPeople.zero" :y2="coastChartPeople.zero" stroke="#4a5a66" stroke-width=".3"/><polyline v-for="l in coastChartPeople.lines" :key="l.name" :points="l.points" fill="none" :stroke="l.color" :stroke-width="l.width" :stroke-dasharray="l.dash"/><line :x1="coastChartPeople.x" :x2="coastChartPeople.x" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>0–{{coastChartPeople.hi.toFixed(2)}} M</small></div><div v-if="coastChartRegions" class="comparison-chart"><small>LAND LOST PER REGION · % (scenario in focus)</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Land lost per region"><line x1="0" x2="100" :y1="coastChartRegions.zero" :y2="coastChartRegions.zero" stroke="#4a5a66" stroke-width=".3"/><polyline v-for="l in coastChartRegions.lines" :key="l.name" :points="l.points" fill="none" :stroke="l.color" :stroke-width="l.width" :stroke-dasharray="l.dash"/><line :x1="coastChartRegions.x" :x2="coastChartRegions.x" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>0–{{coastChartRegions.hi.toFixed(0)}} %</small></div><div v-if="coastChartRivers" class="comparison-chart"><small>RIVERS · storm push-back (solid) and salt intrusion (dashed) · km</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="River push-back and salt intrusion"><line x1="0" x2="100" :y1="coastChartRivers.zero" :y2="coastChartRivers.zero" stroke="#4a5a66" stroke-width=".3"/><polyline v-for="l in coastChartRivers.lines" :key="l.name" :points="l.points" fill="none" :stroke="l.color" :stroke-width="l.width" :stroke-dasharray="l.dash"/><line :x1="coastChartRivers.x" :x2="coastChartRivers.x" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>0–{{coastChartRivers.hi.toFixed(0)}} km</small></div></div><p><span v-for="(name,k) in data.coast.block.region_names" :key="name" :style="{color:['#ff6b6b','#ffd166','#7fd1ff','#9fe870','#b388ff'][k%5],marginRight:'1em'}">■ {{name}}</span></p></section>
<section class="comparison outlet-report"><div class="section-label">RIVERS · THE SEA PUSHES BACK · {{coastSummary.year}}</div><p>How far up each channel the daily high water (tidal reach) and the 100-year storm (push-back) stand above the river's own level, how far salt water intrudes, and the river banks the storm floods — today → now.</p><table class="event-table"><thead><tr><th>River</th><th>Tidal reach</th><th>Storm push-back</th><th>Salt intrusion</th><th>Banks flooded</th></tr></thead><tbody><tr v-for="r in coastSummary.rivers" :key="r.name"><td>{{r.name}}</td><td>{{r.tidal_today_km.toFixed(0)}} → {{r.tidal_reach_km.toFixed(0)}} km</td><td>{{r.surge_today_km.toFixed(0)}} → {{r.surge_reach_km.toFixed(0)}} km</td><td>{{r.salt_today_km.toFixed(1)}} → {{r.salt_intrusion_km.toFixed(1)}} km</td><td>{{r.flooded_bank_km2.toFixed(0)}} km²</td></tr></tbody></table><p v-if="coastSummary.islands.length">Islands (land lost): <span v-for="isl in coastSummary.islands" :key="isl.id" style="margin-right:1em">{{isl.region>=0?data.coast.block.region_names[isl.region]:'island'}} #{{isl.id}} ({{isl.land_km2.toFixed(0)}} km², up to {{isl.highest_m.toFixed(1)}} m): <strong v-if="isl.lost_fraction>=.5">{{(isl.lost_fraction*100).toFixed(0)}} %</strong><template v-else>{{(isl.lost_fraction*100).toFixed(0)}} %</template></span></p></section></template><section v-if="hydrograph.length" class="comparison outlet-report"><div class="section-label">HYDROGRAPH · {{chosen&&data.hydrology?.network.channel[chosen.i]?`SELECTED REACH (cell ${hydrographCell})`:`PEAK REACH (cell ${hydrographCell})`}}</div><p>Discharge at the reach over the run with the rainfall rate on the same cell. Click a river cell to move the gauge.</p><div class="outlet-charts"><div class="comparison-chart"><small>DISCHARGE · m³/s</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Discharge hydrograph"><polyline :points="hydrographPath('discharge_m3_s',hydrographMax)" fill="none" stroke="#75bbfa" stroke-width=".7"/><line :x1="hydrographTimePosition" :x2="hydrographTimePosition" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>0–{{hydrographMax.toFixed(1)}} m³/s · 0–{{(visibleFrames.at(-1).forecast.elapsed_seconds/3600).toFixed(0)}} h</small></div><div class="comparison-chart"><small>RAINFALL · mm/h</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Rainfall hyetograph"><polyline :points="hydrographPath('rain_mm_h',hydrographRainMax)" fill="none" stroke="#9fd0ff" stroke-width=".7"/><line :x1="hydrographTimePosition" :x2="hydrographTimePosition" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>0–{{hydrographRainMax.toFixed(1)}} mm/h</small></div></div><p v-if="visibleLandslides.length">Landslides so far: <template v-for="(e,i) in visibleLandslides.slice(-6)" :key="i">{{i?' · ':''}}cell {{e.cell}} → {{e.deposited_in}} ({{(e.volume_m3/1000).toFixed(1)}} ×10³ m³, {{(e.runout_length_m/1000).toFixed(1)}} km)</template>{{visibleLandslides.length>6?` · … ${visibleLandslides.length} in total`:''}}</p></section><div v-if="stormMetrics" class="metrics extra-metrics"><div><small>TROPICAL CYCLONES</small><strong>{{stormMetrics.storm_count}} <em>({{stormMetrics.storms_over_land}} over land)</em></strong></div><div><small>STRONGEST</small><strong class="date">{{stormMetrics.strongest_wind_m_s.toFixed(1)}} m/s · {{categoryInfo(stormMetrics.strongest_category).label}}<template v-if="stormMetrics.lowest_pressure_hpa"> · {{stormMetrics.lowest_pressure_hpa.toFixed(0)}} hPa</template></strong></div><div><small>LANDFALLS / MERGERS / GENESES SO FAR</small><strong class="date">{{stormMetrics.landfalls_so_far}} / {{stormMetrics.mergers_so_far}} / {{stormMetrics.geneses_so_far}}</strong></div><div><small>MAX SURGE · MAX STORM WIND</small><strong class="date">{{stormMetrics.max_surge_m.toFixed(1)}} m · {{stormMetrics.max_storm_wind_m_s.toFixed(0)}} m/s</strong></div><div><small>POTENTIAL INTENSITY · GENESIS INDEX</small><strong class="date">{{stormMetrics.max_potential_intensity_m_s.toFixed(0)}} m/s · {{stormMetrics.max_genesis_index.toFixed(1)}}</strong></div><div v-if="severeMetrics"><small>TORNADO PARAMETER · POSSIBLE CELLS · CAP BROKEN</small><strong class="date">{{severeMetrics.max_stp.toFixed(2)}} · {{severeMetrics.tornado_possible_cells}} · {{severeMetrics.cap_broken_cells}} / {{severeMetrics.capped_cells}}</strong></div></div><div v-else-if="severeMetrics" class="metrics extra-metrics"><div><small>MAX TORNADO PARAMETER</small><strong>{{severeMetrics.max_stp.toFixed(2)}}</strong></div><div><small>TORNADO POSSIBLE CELLS</small><strong>{{severeMetrics.tornado_possible_cells}}</strong></div><div><small>CAP BROKEN / CAPPED CELLS</small><strong class="date">{{severeMetrics.cap_broken_cells}} / {{severeMetrics.capped_cells}}</strong></div><div><small>MAX HELICITY · LOW-LEVEL SHEAR</small><strong class="date">{{severeMetrics.max_helicity.toFixed(0)}} m²/s² · {{severeMetrics.max_low_level_shear.toFixed(1)}} m/s</strong></div><div><small>MAX HEATED CAPE</small><strong>{{severeMetrics.max_cape.toFixed(0)}} <em>J/kg</em></strong></div></div><div v-if="precipitationMetrics" class="metrics extra-metrics"><div><small>PRECIPITATING CELLS</small><strong>{{precipitationMetrics.precipitating_pct.toFixed(0)}} <em>%</em></strong></div><div><small>RATE MEAN (WET) / MAX</small><strong class="date">{{precipitationMetrics.mean_rate_mm_h.toFixed(1)}} / {{precipitationMetrics.max_rate_mm_h.toFixed(1)}} mm/h</strong></div><div><small>INTERVAL ACCUMULATION MEAN / MAX</small><strong class="date">{{precipitationMetrics.mean_accumulation_mm.toFixed(1)}} / {{precipitationMetrics.max_accumulation_mm.toFixed(1)}} mm</strong></div><div><small>THUNDERSTORM / HAIL / SNOW CELLS</small><strong class="date">{{precipitationMetrics.lightning_cells}} / {{precipitationMetrics.hail_cells}} / {{precipitationMetrics.snow_cells}}<template v-if="precipitationMetrics.max_hail_cm>0"> · hail ≤ {{precipitationMetrics.max_hail_cm.toFixed(1)}} cm</template></strong></div><div><small>HAZARDS</small><strong class="date">{{Object.entries(precipitationMetrics.hazard_counts).map(([h,n])=>`${HAZARD_LABELS[h]} ${n}`).join(' · ')||'none'}}</strong></div><div><small>PRECIPITABLE WATER (MEAN)</small><strong>{{precipitationMetrics.mean_precipitable_water_mm.toFixed(1)}} <em>mm</em></strong></div></div><div v-if="cloudMetrics" class="metrics extra-metrics"><div><small>CLOUD COVER / CLOUDY CELLS</small><strong class="date">{{cloudMetrics.cloud_cover_pct.toFixed(0)}} % / {{cloudMetrics.cloudy_pct.toFixed(0)}} %</strong></div><div><small>THUNDERSTORM CELLS</small><strong>{{cloudMetrics.thunderstorm_cells}}</strong></div><div><small>FRONTS COLD / WARM / STATIONARY</small><strong class="date">{{cloudMetrics.cold_front_cells}} / {{cloudMetrics.warm_front_cells}} / {{cloudMetrics.stationary_front_cells}} <em>cells</em></strong></div><div><small>DOMINANT CLOUD</small><strong class="date">{{cloudTypeInfo(cloudMetrics.dominant_type).label}}</strong></div><div><small>MEAN BASE / TOP</small><strong class="date">{{cloudMetrics.mean_base_m===null?'—':cloudMetrics.mean_base_m.toFixed(0)+' / '+cloudMetrics.mean_top_m.toFixed(0)+' m'}}</strong></div><div><small>FRONTAL / CONVECTIVE CELLS · HEATING</small><strong class="date">{{cloudMetrics.frontal_cells}} / {{cloudMetrics.convective_cells}} · {{cloudMetrics.surface_heating_k.toFixed(1)}} K</strong></div></div><div class="metrics"><div><small>GRID RESOLUTION</small><strong>{{grid.nx}} × {{grid.ny}} <em>cells</em></strong></div><div><small>CELL SPACING</small><strong>{{grid.spacing_east_m}} × {{grid.spacing_north_m}} <em>m</em></strong></div><div><small>VALID TIME</small><strong class="date">{{time}}</strong></div></div></article></main>
  <p v-if="error" class="error" role="alert">{{error}}</p><footer><span>TerraFlux Physics / Research viewer v0.1</span><span>{{snapshots.length>1?'Snapshot playback':'Single snapshot'}} · {{data.terrain?'Visual terrain':'Flat surface'}} · No live solver</span></footer>
 </div>
</template>
